        transliteration: "Qaala kallaa fazhabaa bi Aayaatinaaa innaa ma'akum mustami'oon",
        translation: "(Allah) berfirman, \u201cJangan takut (mereka tidak akan dapat membunuhmu)! Maka pergilah kamu berdua dengan membawa ayat-ayat Kami (mukjizat-mukjizat); sungguh, Kami bersamamu mendengarkan (apa yang mereka katakan),",
        shortTafsir: "Mendengar keluhan Nabi Musa, Allah berfirman, \"Hai Musa! Jangan takut terhadap mereka seperti yang kau katakan! Mereka tidak akan pernah dapat membunuhmu. Aku akan tetap memeliharamu dan menolongmu Maka pergilah kamu berdua menghadap mereka dengan membawa ayat-ayat Kami yaitu mukjizat-mukjizat yang telah Kami berikan kepadamu seperti tongkat dan tanganmu. Sungguh, Kami bersamamu memeliharamu dan menolongmu. Aku akan mendengarkan apa yang mereka katakan.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2947",
      ),
      Ayah(
        numberInSurah: 16,
        numberInQuran: 2948,
        juz: 19,
        page: 367,
        arab: "\u0641\u064e\u0623\u0652\u062a\u0650\u064a\u064e\u0627 \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0641\u064e\u0642\u064f\u0648\u0644\u064e\u0627 \u0625\u0650\u0646\u0651\u064e\u0627 \u0631\u064e\u0633\u064f\u0648\u0644\u064f \u0631\u064e\u0628\u0651\u0650 \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",
        transliteration: "Faatiyaa Fir'awna faqoolaaa innaa Rasoolu Rabbil 'aalameen",
        translation: "maka datanglah kamu berdua kepada Fir\u2018aun dan katakan, \u201cSesungguhnya kami adalah rasul-rasul Tuhan seluruh alam,",
        shortTafsir: "Maka datanglah kamu berdua kepada Fir\u2018aun tanpa dihinggapi rasa takut dan katakanlah dengan kesungguhan hati dan kepercayaan diri, \u201cSesungguhnya kami berdua adalah para rasul Tuhan seluruh alam.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2948",
      ),
      Ayah(
        numberInSurah: 17,
        numberInQuran: 2949,
        juz: 19,
        page: 367,
        arab: "\u0623\u064e\u0646\u0652 \u0623\u064e\u0631\u0652\u0633\u0650\u0644\u0652 \u0645\u064e\u0639\u064e\u0646\u064e\u0627 \u0628\u064e\u0646\u0650\u064a \u0625\u0650\u0633\u0652\u0631\u064e\u0627\u0626\u0650\u064a\u0644\u064e",
        transliteration: "An arsil ma'anaa Baneee Israaa'eel",
        translation: "lepaskanlah Bani Israil (pergi) bersama kami.\u201d",
        shortTafsir: "Lepaskanlah bangsa kami yaitu Bani Israil biarkan mereka pergi bersama kami ketempat yang kami kehendaki. Jangan lagi kau perbudak mereka.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2949",
      ),
      Ayah(
        numberInSurah: 18,
        numberInQuran: 2950,
        juz: 19,
        page: 367,
        arab: "\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0644\u064e\u0645\u0652 \u0646\u064f\u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0641\u0650\u064a\u0646\u064e\u0627 \u0648\u064e\u0644\u0650\u064a\u062f\u064b\u0627 \u0648\u064e\u0644\u064e\u0628\u0650\u062b\u0652\u062a\u064e \u0641\u0650\u064a\u0646\u064e\u0627 \u0645\u0650\u0646\u0652 \u0639\u064f\u0645\u064f\u0631\u0650\u0643\u064e \u0633\u0650\u0646\u0650\u064a\u0646\u064e",
        transliteration: "Qaala alam nurabbika feenaa waleedanw wa labista feenaa min 'umurika sineen",
        translation: "Dia (Fir\u2018aun) menjawab, \u201cBukankah kami telah mengasuhmu dalam lingkungan (keluarga) kami, waktu engkau masih kanak-kanak dan engkau tinggal bersama kami beberapa tahun dari umurmu.",
        shortTafsir: "Mendengar ucapan Nabi Musa, dia Fir\u2018aun, menjawab dengan nada marah dan mengungkit jasanya terhadap Nabi Musa di masa lalu, \u201cBukankah kami telah mengasuhmu, memeliharamu dengan sebaik-baiknya dalam lingkungan keluarga kami, yaitu waktu engkau masih kanak-kanak dan engkau tinggal bersama kami beberapa tahun dari umurmu yaitu semenjak engkau masih bayi sampai engkau menjadi pemuda?\"",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2950",
      ),
      Ayah(
        numberInSurah: 19,
        numberInQuran: 2951,
        juz: 19,
        page: 367,
        arab: "\u0648\u064e\u0641\u064e\u0639\u064e\u0644\u0652\u062a\u064e \u0641\u064e\u0639\u0652\u0644\u064e\u062a\u064e\u0643\u064e \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0641\u064e\u0639\u064e\u0644\u0652\u062a\u064e \u0648\u064e\u0623\u064e\u0646\u062a\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e",
        transliteration: "Wa fa'alta fa'latakal latee fa'alta wa anta minal kaafireen",
        translation: "Dan engkau (Musa) telah melakukan (kesalahan dari) perbuatan yang telah engkau lakukan dan engkau termasuk orang yang tidak tahu berterima kasih.\u201d",
        shortTafsir: "Fir\u2019aun melanjutkan bicaranya dengan mengungkit kesalahan Nabi Musa, \"Dan engkau, Musa, telah melakukan kesalahan pada perbuatan yang telah engkau lakukan dengan membunuh salah seorang bangsaku dan engkau termasuk orang yang tidak tahu berterima kasih.\"",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2951",
      ),
      Ayah(
        numberInSurah: 20,
        numberInQuran: 2952,
        juz: 19,
        page: 368,
        arab: "\u0642\u064e\u0627\u0644\u064e \u0641\u064e\u0639\u064e\u0644\u0652\u062a\u064f\u0647\u064e\u0627 \u0625\u0650\u0630\u064b\u0627 \u0648\u064e\u0623\u064e\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0636\u0651\u064e\u0627\u0644\u0651\u0650\u064a\u0646\u064e",
        transliteration: "Qaala fa'altuhaaa izanw wa ana minad daaaleen",
        translation: "Dia (Musa) berkata, \u201cAku telah melakukannya, dan ketika itu aku termasuk orang yang khilaf.",
        shortTafsir: "Nabi Musa berkata, \u201cAku telah melakukannya, yakni pembunuhan terhadap seorang Qibti tanpa aku sengaja dan ketika itu aku termasuk orang yang khilaf bahwa pukulanku terhadapnya akan mengakibatkan kematiannya, padahal aku memukulnya dengan tujuan untuk memberikan pelajaran kepadanya.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2952",
      ),
      Ayah(
        numberInSurah: 21,
        numberInQuran: 2953,
        juz: 19,
        page: 368,
        arab: "\u0641\u064e\u0641\u064e\u0631\u064e\u0631\u0652\u062a\u064f \u0645\u0650\u0646\u0643\u064f\u0645\u0652 \u0644\u064e\u0645\u0651\u064e\u0627 \u062e\u0650\u0641\u0652\u062a\u064f\u0643\u064f\u0645\u0652 \u0641\u064e\u0648\u064e\u0647\u064e\u0628\u064e \u0644\u0650\u064a \u0631\u064e\u0628\u0651\u0650\u064a \u062d\u064f\u0643\u0652\u0645\u064b\u0627 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e\u0646\u0650\u064a \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0631\u0652\u0633\u064e\u0644\u0650\u064a\u0646\u064e",
        transliteration: "Fafarartu minkum lam maa khiftukum fawahaba lee Rabbee hukmanw wa ja'alanee minal mursaleen",
        translation: "Lalu aku lari darimu karena aku takut kepadamu, kemudian Tuhanku menganugerahkan ilmu kepadaku serta Dia menjadikan aku salah seorang di antara rasul-rasul.",
        shortTafsir: "\"Lalu aku lari darimu menuju ke negeri Madyan, karena aku takut kepadamu pada pembalasan-mu. Kemudian Tuhanku yang memeliharaku menganugerahkan ilmu yang bermanfaat kepadaku serta Dia menjadikan aku salah seorang di antara para rasul sebagaimana para rasul yang lain sebelumku.\"",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2953",
      ),
      Ayah(
        numberInSurah: 22,
        numberInQuran: 2954,
        juz: 19,
        page: 368,
        arab: "\u0648\u064e\u062a\u0650\u0644\u0652\u0643\u064e \u0646\u0650\u0639\u0652\u0645\u064e\u0629\u064c \u062a\u064e\u0645\u064f\u0646\u0651\u064f\u0647\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0651\u064e \u0623\u064e\u0646\u0652 \u0639\u064e\u0628\u0651\u064e\u062f\u062a\u0651\u064e \u0628\u064e\u0646\u0650\u064a \u0625\u0650\u0633\u0652\u0631\u064e\u0627\u0626\u0650\u064a\u0644\u064e",
        transliteration: "Wa tilka ni'matun tamun nuhaa 'alaiya an 'abbatta Baneee Israaa'eel",
        translation: "Dan itulah kebaikan yang telah engkau berikan kepadaku, (sementara) itu engkau telah memperbudak Bani Israil.\u201d",
        shortTafsir: "Lalu Nabi Musa membandingkan antara kebaikan yang dia terima dari Fir\u2019aun dengan kekejaman Fir\u2019aun terhadap Bani Israil. Musa berkata lagi, \"Dan itulah kebaikan yang telah engkau berikan kepadaku, engkau pelihara diriku ketika aku masih bayi sampai aku dewasa. Sementara itu engkau telah memperbudak Bani Israil, kaumku sendiri. Engkau perlakukan mereka dengan tidak berperikemanusiaan. Sungguh ini dua hal yang tidak sebanding. Jika bukan karena kekejamanmu, ibuku tidak akan melemparkan aku ke sungai, dan tidak akan kau pelihara diriku.\"",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2954",
      ),
      Ayah(
        numberInSurah: 23,
        numberInQuran: 2955,
        juz: 19,
        page: 368,
        arab: "\u0642\u064e\u0627\u0644\u064e \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064f \u0648\u064e\u0645\u064e\u0627 \u0631\u064e\u0628\u0651\u064f \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",
        transliteration: "Qaala Fir'awnu wa maa Rabbul 'aalameen",
        translation: "Fir\u2018aun bertanya, \u201cSiapa Tuhan seluruh alam itu?\u201d",
        shortTafsir: "Fir\u2019aun penasaran terhadap perkataan Nabi Musa bahwa dia dan sudaranya Harun diutus oleh Allah Rabbul \u2018alamin. Fir\u2018aun bertanya kepada Musa, \u201cSiapa Tuhan pencipta dan pemelihara seluruh alam itu?\"",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2955",
      ),
      Ayah(
        numberInSurah: 24,
        numberInQuran: 2956,
        juz: 19,
        page: 368,
        arab: "\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u06d6 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645 \u0645\u0651\u064f\u0648\u0642\u0650\u0646\u0650\u064a\u0646\u064e",
        transliteration: "Qaala Rabbus samaawaati wal ardi wa maa bainahumaa in kuntum mooqineen",
        translation: "Dia (Musa) menjawab, \u201cTuhan pencipta langit dan bumi dan apa yang ada di antara keduanya (itulah Tuhanmu), jika kamu mempercayai-Nya.\u201d",
        shortTafsir: "Musa menjawab dengan tiga jawaban. Pertama: \u201cTuhan yang mengutusku adalah Tuhan pencipta, pengurus, pemelihara langit dan bumi dan apa yang ada di antara keduanya seperti benda-benda langit dan lainnya. Hal berbeda dengan dirimu yang hanya meguasai negeri Mesir dengan kekuatanmu. Aku katakan hal ini kepadamu dengan sebenar-benarnya, jika kamu mempercayai-Nya.\"",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2956",
      ),
      Ayah(
        numberInSurah: 25,
        numberInQuran: 2957,
        juz: 19,
        page: 368,
        arab: "\u0642\u064e\u0627\u0644\u064e \u0644\u0650\u0645\u064e\u0646\u0652 \u062d\u064e\u0648\u0652\u0644\u064e\u0647\u064f \u0623\u064e\u0644\u064e\u0627 \u062a\u064e\u0633\u0652\u062a\u064e\u0645\u0650\u0639\u064f\u0648\u0646\u064e",
        transliteration: "Qaala liman hawlahooo alaa tastami'oon",
        translation: "Dia (Fir\u2018aun) berkata kepada orang-orang di sekelilingnya, \u201cApakah kamu tidak mendengar (apa yang dikatakannya)?\u201d",
        shortTafsir: "Mendengar jawaban Nabi Musa ini, Fir\u2019aun terasa mulai tersentak. Dia, yakni Fir\u2018aun, berkata kepada orang-orang di sekelilingnya, yaitu para pembesar kerajaan, \u201cApakah kamu tidak mendengar apa yang dikatakannya?\u201d",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2957",
      ),
      Ayah(
        numberInSurah: 26,
        numberInQuran: 2958,
        juz: 19,
        page: 368,
        arab: "\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645\u0652 \u0648\u064e\u0631\u064e\u0628\u0651\u064f \u0622\u0628\u064e\u0627\u0626\u0650\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",
        transliteration: "Qaala Rabbukum wa Rabbu aabaaa'ikumul awwaleen",
        translation: "Dia (Musa) berkata, \u201c(Dia) Tuhanmu dan juga Tuhan nenek moyangmu terdahulu.\u201d",
        shortTafsir: "Jawaban kedua, \"Dia yakni Musa berkata kepada Fir\u2019aun, \u201cDia itu adalah Tuhanmu dan juga Tuhan nenek moyangmu terdahulu.\u201d Tuhanku itu satu, tidak ada yang lain. Dialah pencipta alam seluruh dan pencipta manusia dari dahulu sampai kini dan sampai kapan pun, termasuk engkau Fir\u2019aun dan kaummu.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2958",
      ),
      Ayah(
        numberInSurah: 27,
        numberInQuran: 2959,
        juz: 19,
        page: 368,
        arab: "\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064f\u0631\u0652\u0633\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0644\u064e\u0645\u064e\u062c\u0652\u0646\u064f\u0648\u0646\u064c",
        transliteration: "Qaala inna Rasoolakumul lazee ursila ilaikum lamajnoon",
        translation: "Dia (Fir\u2018aun) berkata, \u201cSungguh, Rasulmu yang diutus kepada kamu benar-benar orang gila.\u201d",
        shortTafsir: "Fir\u2019aun semakin geram dan marah. Dia yakni Fir\u2018aun berkata kepada para pembesar itu dengan penuh kemarahan, \u201cSungguh, Rasulmu yang diutus kepada kamu benar-benar orang gila.\u201d Dia mengatakan sesuatu yang tidak biasa aku dengar.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2959",
      ),
      Ayah(
        numberInSurah: 28,
        numberInQuran: 2960,
        juz: 19,
        page: 368,
        arab: "\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u064f \u0627\u0644\u0652\u0645\u064e\u0634\u0652\u0631\u0650\u0642\u0650 \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u063a\u0652\u0631\u0650\u0628\u0650 \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u06d6 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0642\u0650\u0644\u064f\u0648\u0646\u064e",
        transliteration: "Qaala Rabbul mashriqi wal maghribi wa maa baina humaa in kuntum ta'qiloon",
        translation: "Dia (Musa) berkata, \u201c(Dialah) Tuhan (yang menguasai) timur dan barat dan apa yang ada di antara keduanya; jika kamu mengerti.\u201d",
        shortTafsir: "Jawaban terakhir, merupakan jawaban yang telak dan sulit bagi Fir\u2019aun untuk mengelak darinya. Nabi Musa, berkata kepada Fir\u2019aun dengan perkataan yang pernah diucapkan juga oleh Nabi Ibrahim kepada penguasa yang zalim (Lihat: Al-Baqarah/2: 258), \u201cKetiga, Dialah Tuhan yang menguasai ufuk timur tempat terbit matahari dan ufuk barat tempat terbenamnya matahari dan apa yang ada di antara ke-duanya, seperti gunung-gunung, lautan dan lain sebagainya, jika kamu mengerti, dan menggunakan akalmu dengan baik dan benar. Janganlah kau terus menerus dengan kebatilan, padahal kau tahu kebenaran. Apakah kamu mampu melakukan apa yang dilakukan Tuhanku?",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2960",
      ),
      Ayah(
        numberInSurah: 29,
        numberInQuran: 2961,
        juz: 19,
        page: 368,
        arab: "\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0626\u0650\u0646\u0650 \u0627\u062a\u0651\u064e\u062e\u064e\u0630\u0652\u062a\u064e \u0625\u0650\u0644\u064e\u0670\u0647\u064b\u0627 \u063a\u064e\u064a\u0652\u0631\u0650\u064a \u0644\u064e\u0623\u064e\u062c\u0652\u0639\u064e\u0644\u064e\u0646\u0651\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064e\u0633\u0652\u062c\u064f\u0648\u0646\u0650\u064a\u0646\u064e",
        transliteration: "Qaala la'init takhazta ilaahan ghairee la aj'alannaka minal masjooneen",
        translation: "Dia (Fir\u2018aun) berkata, \u201cSungguh, jika engkau menyembah Tuhan selain aku, pasti aku masukkan engkau ke dalam penjara.\u201d",
        shortTafsir: "Fir\u2019aun semakin berang mendengar perkataan Nabi Musa dan mulai menggunakan kekuatannya, sebagaimana juga penguasa yang zalim, untuk membungkam musuh-musuh mereka. Fir\u2018aun berkata dengan nada mengancam, \u201cSungguh, jika engkau menyembah Tuhan selain aku, pasti aku masukkan engkau ke dalam penjara. Sebagaimana orang-orang yang telah aku penjarakan. Aku akan siksa dirimu dengan siksaan yang amat pedih.\"",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2961",
      ),
      Ayah(
        numberInSurah: 30,
        numberInQuran: 2962,
        juz: 19,
        page: 368,
        arab: "\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0648\u064e\u0644\u064e\u0648\u0652 \u062c\u0650\u0626\u0652\u062a\u064f\u0643\u064e \u0628\u0650\u0634\u064e\u064a\u0652\u0621\u064d \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u064d",
        transliteration: "Qaala awalw ji'tuka bishai'im mubeen",
        translation: "Dia (Musa) berkata, \u201cApakah (engkau akan melakukan itu) sekalipun aku tunjukkan kepadamu sesuatu (bukti) yang nyata?\u201d",
        shortTafsir: "Nabi Musa sama sekali tidak gentar dengan ancaman itu, karena yakin Allah selalu bersamanya. Dengan hati yang tenang, Nabi Musa menawarkan kepada Fir\u2019aun satu tawaran. Dia Musa berkata, \u201cApakah engkau tetap akan memenjarakanku sekalipun aku tunjukkan kepadamu sesuatu bukti yang nyata sebagai tanda bahwa aku adalah benar-benar utusan Tuhanku?\"",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2962",
      ),
      Ayah(
        numberInSurah: 31,
        numberInQuran: 2963,
        juz: 19,
        page: 368,
        arab: "\u0642\u064e\u0627\u0644\u064e \u0641\u064e\u0623\u0652\u062a\u0650 \u0628\u0650\u0647\u0650 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u062f\u0650\u0642\u0650\u064a\u0646\u064e",
        transliteration: "Qaala faati biheee in kunta minas saadiqeen",
        translation: "Dia (Fir\u2018aun) berkata, \u201cTunjukkan sesuatu (bukti yang nyata) itu, jika engkau termasuk orang yang benar!\u201d",
        shortTafsir: "Fir\u2018aun berkata, baiklah kalau begitu. Aku tidak akan memenjarakanmu, tetapi tunjukkan sesuatu bukti yang nyata yang kau janjikan itu jika engkau termasuk orang yang benar terhadap pengakuanmu itu bahwa engkau adalah benar-benar utusan Tuhan!\" Tidak berselang lama, Nabi Musa memperlihatkan kepada Fir\u2019aun apa yang ditawarkannya, yaitu tongkat yang bisa berubah menjadi ular dan tangan yang mengeluarkan sinar yang berkilauan.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2963",
      ),
      Ayah(
        numberInSurah: 32,
        numberInQuran: 2964,
        juz: 19,
        page: 368,
        arab: "\u0641\u064e\u0623\u064e\u0644\u0652\u0642\u064e\u0649\u0670 \u0639\u064e\u0635\u064e\u0627\u0647\u064f \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0647\u0650\u064a\u064e \u062b\u064f\u0639\u0652\u0628\u064e\u0627\u0646\u064c \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u064c",
        transliteration: "Fa alqaa 'asaahu fa izaaa hiya su'baanum mubeen",
        translation: "Maka dia (Musa) melemparkan tongkatnya, tiba-tiba tongkat itu menjadi ular besar yang sebenarnya.",
        shortTafsir: "Maka Musa melemparkan tongkatnya yang dahulu dia gunakan untuk menggembala kambing di negeri Madyan, tiba-tiba tongkat itu atas izin Allah berubah menjadi ular besar yang sebenarnya. Bukan tipuan sebagaimana yang dilakukan oleh para pesihir. Dengan peristiwa ini, Allah mampu mengubah benda mati menjadi benda yang hidup. Maka kebangkitan manusia di hari Kiamat bukanlah sesuatu yang sulit bagi Allah.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2964",
      ),
      Ayah(
        numberInSurah: 33,
        numberInQuran: 2965,
        juz: 19,
        page: 368,
        arab: "\u0648\u064e\u0646\u064e\u0632\u064e\u0639\u064e \u064a\u064e\u062f\u064e\u0647\u064f \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0647\u0650\u064a\u064e \u0628\u064e\u064a\u0652\u0636\u064e\u0627\u0621\u064f \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0638\u0650\u0631\u0650\u064a\u0646\u064e",
        transliteration: "Wa naza'a yadahoo faizaa hiya baidaaa'u linnaa zireen",
        translation: "Dan dia mengeluarkan tangannya (dari dalam bajunya), tiba-tiba tangan itu menjadi putih (bercahaya) bagi orang-orang yang melihatnya.",
        shortTafsir: "Fir\u2019aun mencoba memengaruhi para pembesarnya agar jangan terpengaruh oleh ajakan Nabi Musa. Fir\u2018aun, berkata kepada para pemuka di sekelilingnya, \u201cSesungguhnya dia ini pasti seorang pesihir yang sangat pandai, maka janganlah kamu sekalian tertipu olehnya.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2965",
      ),
      Ayah(
        numberInSurah: 34,
        numberInQuran: 2966,
        juz: 19,
        page: 368,
        arab: "\u0642\u064e\u0627\u0644\u064e \u0644\u0650\u0644\u0652\u0645\u064e\u0644\u064e\u0625\u0650 \u062d\u064e\u0648\u0652\u0644\u064e\u0647\u064f \u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0644\u064e\u0633\u064e\u0627\u062d\u0650\u0631\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u064c",
        transliteration: "Qaala lilmala-i hawlahooo inna haazaa lasaahirun 'aleem",
        translation: "Dia (Fir\u2018aun) berkata kepada para pemuka di sekelilingnya, \u201cSesungguhnya dia (Musa) ini pasti seorang pesihir yang pandai,",
        shortTafsir: "Dia hendak mengusir kamu dari negerimu yang subur makmur ini, di mana kamu hidup enak dan tenang di dalamnya, dengan ilmu sihirnya. Oleh karena itu apakah yang kamu sarankan kepadaku sehingga aku bisa melaksanakannya?\u201d Fir\u2019aun merasa terdesak sehingga meminta pertimbangan dari para pembesarnya. Pengusiran seorang dari negerinya adalah sebuah prahara kehidupan, karena mereka harus meninggalkan apa yang mereka cintai. Fir\u2019aun menggunakan taktik ini agar mereka merasa tersentak dan akhirnya melawan Nabi Musa.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2966",
      ),
      Ayah(
        numberInSurah: 35,
        numberInQuran: 2967,
        juz: 19,
        page: 368,
        arab: "\u064a\u064f\u0631\u0650\u064a\u062f\u064f \u0623\u064e\u0646 \u064a\u064f\u062e\u0652\u0631\u0650\u062c\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u0652 \u0623\u064e\u0631\u0652\u0636\u0650\u0643\u064f\u0645 \u0628\u0650\u0633\u0650\u062d\u0652\u0631\u0650\u0647\u0650 \u0641\u064e\u0645\u064e\u0627\u0630\u064e\u0627 \u062a\u064e\u0623\u0652\u0645\u064f\u0631\u064f\u0648\u0646\u064e",
        transliteration: "Yureedu ai yukhrijakum min ardikum bisihrihee famaazaa taamuroon",
        translation: "dia hendak mengusir kamu dari negerimu dengan sihirnya; karena itu apakah yang kamu sarankan?\u201d",
        shortTafsir: "Para pembesar itu menawarkan kepada Fir\u2019aun agar diadakan perang tanding antara Nabi Musa dan para pesihir Mesir. Mereka menjawab, \u201cTahanlah untuk sementara, jangan kau bunuh dia yaitu Musa dan saudaranya yaitu nabi Harun, dan utuslah ke seluruh negeri Mesir orang-orang yang akan mengumpulkan penyihir, niscaya mereka akan mendatangkan semua pesihir yang pandai kepadamu.\u201d",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2967",
      ),
      Ayah(
        numberInSurah: 36,
        numberInQuran: 2968,
        juz: 19,
        page: 368,
        arab: "\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0623\u064e\u0631\u0652\u062c\u0650\u0647\u0652 \u0648\u064e\u0623\u064e\u062e\u064e\u0627\u0647\u064f \u0648\u064e\u0627\u0628\u0652\u0639\u064e\u062b\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0645\u064e\u062f\u064e\u0627\u0626\u0650\u0646\u0650 \u062d\u064e\u0627\u0634\u0650\u0631\u0650\u064a\u0646\u064e",
        transliteration: "Qaalooo arjih wa akhaahu wab'as filmadaaa'ini haashireen",
        translation: "Mereka menjawab, \u201cTahanlah (untuk sementara) dia dan saudaranya, dan utuslah ke seluruh negeri orang-orang yang akan mengumpulkan (pesihir),",
        shortTafsir: "Para pembesar itu menawarkan kepada Fir\u2019aun agar diadakan perang tanding antara Nabi Musa dan para pesihir Mesir. Mereka menjawab, \u201cTahanlah untuk sementara, jangan kau bunuh dia yaitu Musa dan saudaranya yaitu nabi Harun, dan utuslah ke seluruh negeri Mesir orang-orang yang akan mengumpulkan penyihir, niscaya mereka akan mendatangkan semua pesihir yang pandai kepadamu.\u201d",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2968",
      ),
      Ayah(
        numberInSurah: 37,
        numberInQuran: 2969,
        juz: 19,
        page: 368,
        arab: "\u064a\u064e\u0623\u0652\u062a\u064f\u0648\u0643\u064e \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0633\u064e\u062d\u0651\u064e\u0627\u0631\u064d \u0639\u064e\u0644\u0650\u064a\u0645\u064d",
        transliteration: "Yaatooka bikulli sah haarin 'aleem",
        translation: "niscaya mereka akan mendatangkan semua pesihir yang pandai kepadamu.\u201d",
        shortTafsir: "Para pembesar itu menawarkan kepada Fir\u2019aun agar diadakan perang tanding antara Nabi Musa dan para pesihir Mesir. Mereka menjawab, \u201cTahanlah untuk sementara, jangan kau bunuh dia yaitu Musa dan saudaranya yaitu nabi Harun, dan utuslah ke seluruh negeri Mesir orang-orang yang akan mengumpulkan penyihir, niscaya mereka akan mendatangkan semua pesihir yang pandai kepadamu.\u201d",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2969",
      ),
      Ayah(
        numberInSurah: 38,
        numberInQuran: 2970,
        juz: 19,
        page: 368,
        arab: "\u0641\u064e\u062c\u064f\u0645\u0650\u0639\u064e \u0627\u0644\u0633\u0651\u064e\u062d\u064e\u0631\u064e\u0629\u064f \u0644\u0650\u0645\u0650\u064a\u0642\u064e\u0627\u062a\u0650 \u064a\u064e\u0648\u0652\u0645\u064d \u0645\u0651\u064e\u0639\u0652\u0644\u064f\u0648\u0645\u064d",
        transliteration: "Fa jumi'as saharatu limeeqaati Yawmim ma'loom",
        translation: "Lalu dikumpulkanlah para pesihir pada waktu (yang ditetapkan) pada hari yang telah ditentukan,",
        shortTafsir: "Lalu dikumpulkanlah para pesihir pada waktu pagi pada hari yang telah ditentukan, yaitu pada hari raya mereka, di mana mereka berhias diri untuk bersenang-senang (Lihat: Surah Thaha/20: 59).",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2970",
      ),
      Ayah(
        numberInSurah: 39,
        numberInQuran: 2971,
        juz: 19,
        page: 368,
        arab: "\u0648\u064e\u0642\u0650\u064a\u0644\u064e \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0647\u064e\u0644\u0652 \u0623\u064e\u0646\u062a\u064f\u0645 \u0645\u0651\u064f\u062c\u0652\u062a\u064e\u0645\u0650\u0639\u064f\u0648\u0646\u064e",
        transliteration: "Wa qeela linnaasi hal antum mujtami'oon",
        translation: "dan diumumkan kepada orang banyak, \u201cBerkumpullah kamu semua,",
        shortTafsir: "Dan diumumkan kepada orang banyak untuk segera berkumpul menyaksikan pertandingan yang sangat menentukan nasib para petarung, apakah Nabi Musa atau para penyihir itu. \u201cBerkumpullah kamu semua, jangan ada di antara kamu yang tertinggal.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2971",
      ),
      Ayah(
        numberInSurah: 40,
        numberInQuran: 2972,
        juz: 19,
        page: 369,
        arab: "\u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0646\u064e\u0627 \u0646\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f \u0627\u0644\u0633\u0651\u064e\u062d\u064e\u0631\u064e\u0629\u064e \u0625\u0650\u0646 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0647\u064f\u0645\u064f \u0627\u0644\u0652\u063a\u064e\u0627\u0644\u0650\u0628\u0650\u064a\u0646\u064e",
        transliteration: "La'allanaa nattabi'us saharata in kaanoo humul ghaalibeen",
        translation: "agar kita mengikuti para pesihir itu, jika mereka yang menang.\u201d",
        shortTafsir: "\"Tujuannya adalah agar kita mengikuti para pesihir itu, jika mereka yang menang dalam perang tanding ini.\" Untuk mengalahkan Nabi Musa, Ternyata Fir\u2019aun yang mengaku-ngaku sebagai Tuhan, masih menggunakan orang lain, seperti penyihir, bukan kekuatan dirinya.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2972",
      ),
      Ayah(
        numberInSurah: 41,
        numberInQuran: 2973,
        juz: 19,
        page: 369,
        arab: "\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0621\u064e \u0627\u0644\u0633\u0651\u064e\u062d\u064e\u0631\u064e\u0629\u064f \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u0650\u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0623\u064e\u0626\u0650\u0646\u0651\u064e \u0644\u064e\u0646\u064e\u0627 \u0644\u064e\u0623\u064e\u062c\u0652\u0631\u064b\u0627 \u0625\u0650\u0646 \u0643\u064f\u0646\u0651\u064e\u0627 \u0646\u064e\u062d\u0652\u0646\u064f \u0627\u0644\u0652\u063a\u064e\u0627\u0644\u0650\u0628\u0650\u064a\u0646\u064e",
        transliteration: "Falammaa jaaa'as saharatu qaaloo li Fir'awna a'inna lanaa la ajjran in kunnaa nahnul ghaalibeen",
        translation: "Maka ketika para pesihir datang, mereka berkata kepada Fir\u2018aun, \u201cApakah kami benar-benar akan mendapat imbalan yang besar jika kami yang menang?\u201d",
        shortTafsir: "Maka ketika para pesihir datang, mereka berkata kepada Fir\u2018aun untuk meminta janji imbalan, \u201cApakah kami benar-benar akan mendapat imbalan yang besar jika kami yang menang melawan Musa?\" Demikianlah para pesihir bersedia membela Fir\u2019aun bukan karena mempertahankan kebenaran tapi menginginkan imbalan yang besar.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2973",
      ),
      Ayah(
        numberInSurah: 42,
        numberInQuran: 2974,
        juz: 19,
        page: 369,
        arab: "\u0642\u064e\u0627\u0644\u064e \u0646\u064e\u0639\u064e\u0645\u0652 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0625\u0650\u0630\u064b\u0627 \u0644\u0651\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0642\u064e\u0631\u0651\u064e\u0628\u0650\u064a\u0646\u064e",
        transliteration: "Qaala na'am wa innakum izal laminal muqarrabeen",
        translation: "Dia (Fir\u2018aun) menjawab, \u201cYa, dan bahkan kamu pasti akan mendapat kedudukan yang dekat (kepadaku).\u201d",
        shortTafsir: "Fir\u2018aun menjawab, \u201cYa, kalian akan mendapatkan imbalan yang besar dan bahkan di samping itu, kamu pasti akan mendapat kedudukan yang dekat kepadaku, dengan kedudukan itu kamu pasti akan mendapatkan fasilitas-fsilitas terbaik dariku.\"",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2974",
      ),
      Ayah(
        numberInSurah: 43,
        numberInQuran: 2975,
        juz: 19,
        page: 369,
        arab: "\u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u064f\u0648\u0633\u064e\u0649\u0670 \u0623\u064e\u0644\u0652\u0642\u064f\u0648\u0627 \u0645\u064e\u0627 \u0623\u064e\u0646\u062a\u064f\u0645 \u0645\u0651\u064f\u0644\u0652\u0642\u064f\u0648\u0646\u064e",
        transliteration: "Qaala lahum Moosaaa alqoo maaa antum mulqoon",
        translation: "Dia (Musa) berkata kepada mereka, \u201cLemparkanlah apa yang hendak kamu lemparkan.\u201d",
        shortTafsir: "Para pesihir mempersilakan Nabi Musa memperlihatkan kehebatannya terlebih dahulu (Lihat: Surah Al-A\u2019r\u00e0f/7: 115). Namun sebelumnya Nabi Musa mengingatkan mereka agar tidak meneruskan perang tanding ini karena mereka pasti kalah (Lihat: Surah T\u00e0ha:61). Akan tetapi, mereka tetap dengan pendirian mereka. Perang tanding pun dimulai. Musa, berkata kepada mereka para pesihir itu, \"Sekarang aku berikan kesempatan kepada kalian, Lemparkanlah apa yang hendak kamu lemparkan, agar nanti bisa terlihat mana yang benar dan mana yang batil.\" Lain halnya jika Nabi Musa terlebih dahulu yang beraksi.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2975",
      ),
      Ayah(
        numberInSurah: 44,
        numberInQuran: 2976,
        juz: 19,
        page: 369,
        arab: "\u0641\u064e\u0623\u064e\u0644\u0652\u0642\u064e\u0648\u0652\u0627 \u062d\u0650\u0628\u064e\u0627\u0644\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0639\u0650\u0635\u0650\u064a\u0651\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0628\u0650\u0639\u0650\u0632\u0651\u064e\u0629\u0650 \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0646\u064e\u062d\u0652\u0646\u064f \u0627\u0644\u0652\u063a\u064e\u0627\u0644\u0650\u0628\u064f\u0648\u0646\u064e",
        transliteration: "Fa alqaw hibaalahum wa 'isiyyahum wa qaaloo bi'izzati Fir'awna innaa lanahnul ghaaliboon",
        translation: "Lalu mereka melemparkan tali temali dan tongkat-tongkat mereka seraya berkata, \u201cDemi kekuasaan Fir\u2018aun, pasti kamilah yang akan menang.\u201d",
        shortTafsir: "Lalu mereka melemparkan tali temali dan tongkat-tongkat mereka seraya berkata dan bersumpah dengan penuh keyakinan, \u201cDemi kekuasaan Fir\u2018aun, pasti kamilah yang akan menang.\u201d Tongkat dan tali temali yang dilemparkan para pesihir itu terlihat oleh pengunjung seperti ular-ular yang berkeliaran ke sana ke mari yang menakutkan. Inilah puncak prestasi sihir mereka. Melihat gelagat ini, Nabi Musa merasa takut, tapi Allah menentramkannya, \"Wahai Musa, jangan takut, kamu pasti menang\u201d Allah kemudian memerintahkan Nabi Musa untuk melemparkan tongkatnya.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2976",
      ),
      Ayah(
        numberInSurah: 45,
        numberInQuran: 2977,
        juz: 19,
        page: 369,
        arab: "\u0641\u064e\u0623\u064e\u0644\u0652\u0642\u064e\u0649\u0670 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0639\u064e\u0635\u064e\u0627\u0647\u064f \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0647\u0650\u064a\u064e \u062a\u064e\u0644\u0652\u0642\u064e\u0641\u064f \u0645\u064e\u0627 \u064a\u064e\u0623\u0652\u0641\u0650\u0643\u064f\u0648\u0646\u064e",
        transliteration: "Fa alqaa Moosaa 'asaahu fa izaa hiya talqafu maa yaafikoon",
        translation: "Kemudian Musa melemparkan tongkatnya, maka tiba-tiba ia menelan benda-benda palsu yang mereka ada-adakan itu.",
        shortTafsir: "Kemudian Musa melemparkan tongkatnya, maka tiba-tiba saja tongkat itu berubah menjadi ular besar yang sangat menakutkan, kemudian ia, ular besar itu menelan benda-benda yang kelihatan seperti ular itu, padahal itu adalah benda-benda yang palsu yang mereka ada-adakan itu, karena berasal dari sihir, dan sihir itu berasal dari setan.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2977",
      ),
      Ayah(
        numberInSurah: 46,
        numberInQuran: 2978,
        juz: 19,
        page: 369,
        arab: "\u0641\u064e\u0623\u064f\u0644\u0652\u0642\u0650\u064a\u064e \u0627\u0644\u0633\u0651\u064e\u062d\u064e\u0631\u064e\u0629\u064f \u0633\u064e\u0627\u062c\u0650\u062f\u0650\u064a\u0646\u064e",
        transliteration: "Fa ulqiyas saharatu saajideen",
        translation: "Maka menyungkurlah para pesihir itu, bersujud.",
        shortTafsir: "Sehabis menelan \u201cular-ular\u201d para pesihir, Nabi Musa mengambil tongkatnya kembali. Melihat kejadian yang sangat dramatis ini, para pesihir tertegun, terpana, dan merasa terkalahkan. Mereka yakin bahwa Nabi Musa bukanlah penyihir. Lalu serta merta mereka bersujud. Maka, tanpa menunggu lebih lama lagi menyungkurlah para pesihir itu, bersujud di tanah tanpa ragu-ragu, karena mereka telah menemukan kebenaran.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2978",
      ),
      Ayah(
        numberInSurah: 47,
        numberInQuran: 2979,
        juz: 19,
        page: 369,
        arab: "\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0622\u0645\u064e\u0646\u0651\u064e\u0627 \u0628\u0650\u0631\u064e\u0628\u0651\u0650 \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",
        transliteration: "Qaalooo aamannaa bi Rabbil 'aalameen",
        translation: "Mereka berkata, \u201cKami beriman kepada Tuhan seluruh alam,",
        shortTafsir: "Para pesihir berkata dengan penuh keyakinan \u201cKami beriman, yakin, dan percaya kepada Tuhan pencipta seluruh alam sebagaimana yang diyakini oleh Musa, yaitu Tuhan Musa dan Harun, Tuhan seluruh alam.\"",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2979",
      ),
      Ayah(
        numberInSurah: 48,
        numberInQuran: 2980,
        juz: 19,
        page: 369,
        arab: "\u0631\u064e\u0628\u0651\u0650 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0648\u064e\u0647\u064e\u0627\u0631\u064f\u0648\u0646\u064e",
        transliteration: "Rabbi Moosaa wa Haaroon",
        translation: "(yaitu) Tuhannya Musa dan Harun.\u201d",
        shortTafsir: "Para pesihir berkata dengan penuh keyakinan \u201cKami beriman, yakin, dan percaya kepada Tuhan pencipta seluruh alam sebagaimana yang diyakini oleh Musa. yaitu Tuhan Musa dan Harun, Tuhan seluruh alam.\"",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2980",
      ),
      Ayah(
        numberInSurah: 49,
        numberInQuran: 2981,
        juz: 19,
        page: 369,
        arab: "\u0642\u064e\u0627\u0644\u064e \u0622\u0645\u064e\u0646\u062a\u064f\u0645\u0652 \u0644\u064e\u0647\u064f \u0642\u064e\u0628\u0652\u0644\u064e \u0623\u064e\u0646\u0652 \u0622\u0630\u064e\u0646\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0643\u064e\u0628\u0650\u064a\u0631\u064f\u0643\u064f\u0645\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0639\u064e\u0644\u0651\u064e\u0645\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0633\u0651\u0650\u062d\u0652\u0631\u064e \u0641\u064e\u0644\u064e\u0633\u064e\u0648\u0652\u0641\u064e \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u06da \u0644\u064e\u0623\u064f\u0642\u064e\u0637\u0651\u0650\u0639\u064e\u0646\u0651\u064e \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0631\u0652\u062c\u064f\u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u0652 \u062e\u0650\u0644\u064e\u0627\u0641\u064d \u0648\u064e\u0644\u064e\u0623\u064f\u0635\u064e\u0644\u0651\u0650\u0628\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u062c\u0652\u0645\u064e\u0639\u0650\u064a\u0646\u064e",
        transliteration: "Qaala aamantum lahoo qabla an aazana lakum innahoo lakabeerukumul lazee 'alla makumus sihra falasawfa ta'lamoon; la uqatti'anna aidiyakum wa arjulakum min khilaafinw wa la usallibanna kum ajma'een",
        translation: "Dia (Fir\u2018aun) berkata, \u201cMengapa kamu beriman kepada Musa sebelum aku memberi izin kepadamu? Sesungguhnya dia pemimpinmu yang mengajarkan sihir kepadamu. Nanti kamu pasti akan tahu (akibat perbuatanmu). Pasti akan kupotong tangan dan kakimu bersilang dan sungguh, akan kusalib kamu semuanya.\u201d",
        shortTafsir: "Dengan dikalahkannya para pesihir itu, posisi Fir\u2019aun semakin terdesak. Padahal kejadian ini disaksikan banyak sekali penduduk yang berkerumun. Fir\u2019aun lalu berkata kapada para pesihir dengan suara lantang dan menggertak dengan nada geram, \u201cMengapa kamu beriman kepada Musa sebelum aku memberi izin kepadamu? Padahal aku adalah pemimpin yang ditaati dan ditakuti. Sesungguhnya dia, Musa, pemimpinmu yang mengajarkan sihir kepadamu.\" Lalu Fir\u2019aun mengancam mereka, \"Nanti kamu pasti akan tahu akibat perbuatanmu. Pasti akan kupotong tangan dan kakimu bersilang dan sungguh, akan kusalib kamu semuanya di tiang sampai kamu mati di tiang salib itu.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2981",
      ),
      Ayah(
        numberInSurah: 50,
        numberInQuran: 2982,
        juz: 19,
        page: 369,
        arab: "\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u064e\u0627 \u0636\u064e\u064a\u0652\u0631\u064e \u06d6 \u0625\u0650\u0646\u0651\u064e\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0646\u064e\u0627 \u0645\u064f\u0646\u0642\u064e\u0644\u0650\u0628\u064f\u0648\u0646\u064e",
        transliteration: "Qaaloo la daira innaaa ilaa Rabbinaa munqalliboon",
        translation: "Mereka berkata, \u201cTidak ada yang kami takutkan, karena kami akan kembali kepada Tuhan kami.",
        shortTafsir: "Namun ancaman Fir\u2019aun tidak menyurutkan tekad mereka untuk terus beriman kepada Allah. Demikianlah hati jika sudah tenteram dengan keimanan tidak akan mudah goyah dengan ancaman apa pun. Para pesihir itu bahkan berani berterus terang dengan keimanan mereka. Mereka berkata, \u201cTidak ada sama sekali yang kami takutkan dengan semua yang engkau ancamkan kepada kami, karena pada akhirnya kami semua akan mati, kami akan kembali kepada Tuhan kami dan kami harus mempertanggungjawabkan perbuatan kami di hadapan Tuhan kami.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2982",
      ),
      Ayah(
        numberInSurah: 51,
        numberInQuran: 2983,
        juz: 19,
        page: 369,
        arab: "\u0625\u0650\u0646\u0651\u064e\u0627 \u0646\u064e\u0637\u0652\u0645\u064e\u0639\u064f \u0623\u064e\u0646 \u064a\u064e\u063a\u0652\u0641\u0650\u0631\u064e \u0644\u064e\u0646\u064e\u0627 \u0631\u064e\u0628\u0651\u064f\u0646\u064e\u0627 \u062e\u064e\u0637\u064e\u0627\u064a\u064e\u0627\u0646\u064e\u0627 \u0623\u064e\u0646 \u0643\u064f\u0646\u0651\u064e\u0627 \u0623\u064e\u0648\u0651\u064e\u0644\u064e \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",
        transliteration: "Innaa natma'u ai yaghfira lanaa Rabbunna khataa yaanaaa an kunnaaa awwalal mu'mineen",
        translation: "Sesungguhnya kami sangat menginginkan sekiranya Tuhan kami akan mengampuni kesalahan kami, karena kami menjadi orang yang pertama-tama beriman.\u201d",
        shortTafsir: "Mereka terus berkata, \"Sesungguhnya kami sangat menginginkan sekiranya Tuhan kami akan mengampuni segala kesalahan yang kami perbuat karena perbuatan sihir kami, ketaatan kami kepada Fir\u2019aun, dan lain-lainnya, karena kami menjadi orang yang pertama-tama beriman kepada Tuhan Musa dan Harun.\"",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2983",
      ),
      Ayah(
        numberInSurah: 52,
        numberInQuran: 2984,
        juz: 19,
        page: 369,
        arab: "\u06de \u0648\u064e\u0623\u064e\u0648\u0652\u062d\u064e\u064a\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0623\u064e\u0646\u0652 \u0623\u064e\u0633\u0652\u0631\u0650 \u0628\u0650\u0639\u0650\u0628\u064e\u0627\u062f\u0650\u064a \u0625\u0650\u0646\u0651\u064e\u0643\u064f\u0645 \u0645\u0651\u064f\u062a\u0651\u064e\u0628\u064e\u0639\u064f\u0648\u0646\u064e",
        transliteration: "Wa awhainaaa ilaa Moosaaa an asri bi'ibaadeee innakum muttaba'oon",
        translation: "Dan Kami wahyukan (perintahkan) kepada Musa, \u201cPergilah pada malam hari dengan membawa hamba-hamba-Ku (Bani Israil), sebab pasti kamu akan dikejar.\u201d",
        shortTafsir: "Walaupun Fir\u2019aun telah kalah dalam pertarungan, tapi tetap saja dia angkuh dan sombong, dan bahkan terus menindas Bani Israil di Mesir. Nabi Musa terus berdakwah beberapa tahun lamanya. Sampai pada puncaknya, Allah memerintahkan Nabi Musa untuk keluar dari tanah Mesir menuju ke negeri yang dijanjikan yaitu di baitul Maqdis. Dan Kami wahyukan serta Kami perintahkan kepada Musa, \u201cPergilah pada malam hari dengan membawa serta hamba-hamba-Ku, yaitu Bani Israil, keluar dari tanah Mesir, agar mereka lepas dari kezaliman raja Fir\u2019aun, sebab pasti kamu akan dikejar. Jika kamu keluar pada malam hari, kamu akan sampai di tepi laut pada pagi harinya. Mereka yang mengejar di pagi hari tidak akan mampu mengejarmu, karena saat itu kamu sudah berada di laut.\" Mendengar Nabi Musa dan Bani Israil keluar dari Mesir, Fir\u2019aun memerintahkan kaumnya untuk mengejar Nabi Musa dan Bani Israil.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2984",
      ),
      Ayah(
        numberInSurah: 53,
        numberInQuran: 2985,
        juz: 19,
        page: 369,
        arab: "\u0641\u064e\u0623\u064e\u0631\u0652\u0633\u064e\u0644\u064e \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064f \u0641\u0650\u064a \u0627\u0644\u0652\u0645\u064e\u062f\u064e\u0627\u0626\u0650\u0646\u0650 \u062d\u064e\u0627\u0634\u0650\u0631\u0650\u064a\u0646\u064e",
        transliteration: "Fa arsala Fir'awnu filmadaaa'ini haashireen",
        translation: "Kemudian Fir\u2018aun mengirimkan orang ke kota-kota (untuk mengumpulkan bala tentaranya).",
        shortTafsir: "Kemudian Fir\u2018aun mengirimkan orang ke kota-kota untuk memobilisasi umum bala tentaranya dan pengikutnya dalam rangka mengejar Nabi Musa kemudian membunuhnya. Setelah Fir\u2019aun melihat jumlah bala tentaranya demikian besar, dia menganggap remeh Nabi Musa dan Bani Israil. Tapi sebenarnya Fir\u2019aun sudah merasa panik dan galau.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2985",
      ),
      Ayah(
        numberInSurah: 54,
        numberInQuran: 2986,
        juz: 19,
        page: 369,
        arab: "\u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0670\u0624\u064f\u0644\u064e\u0627\u0621\u0650 \u0644\u064e\u0634\u0650\u0631\u0652\u0630\u0650\u0645\u064e\u0629\u064c \u0642\u064e\u0644\u0650\u064a\u0644\u064f\u0648\u0646\u064e",
        transliteration: "Inna haaa'ulaaa'i lashir zimatun qaleeloon",
        translation: "(Fir\u2018aun berkata), \u201cSesungguhnya mereka (Bani Israil) hanya sekelompok kecil,",
        shortTafsir: "Fir\u2018aun berkata kepada para pembesarnya, \u201cSesungguhnya mereka Bani Israil itu hanya sekelompok kecil. Jumlah mereka sangat tidak sebanding dengan tentara kita. Kita akan dengan mudah bisa mengalahkan mereka.\"",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2986",
      ),
      Ayah(
        numberInSurah: 55,
        numberInQuran: 2987,
        juz: 19,
        page: 369,
        arab: "\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0646\u064e\u0627 \u0644\u064e\u063a\u064e\u0627\u0626\u0650\u0638\u064f\u0648\u0646\u064e",
        transliteration: "Wa innahum lanaa laghaaa'izoon",
        translation: "dan sesungguhnya mereka telah berbuat hal-hal yang menimbulkan amarah kita,",
        shortTafsir: "Dan sesungguhnya mereka, Bani Israil itu, telah berbuat hal-hal yang menimbulkan amarah kita, seperti ajakan mereka kepada kita untuk menyembah Tuhan mereka, padahal mereka adalah bawahan dan rakyat jelata kita.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2987",
      ),
      Ayah(
        numberInSurah: 56,
        numberInQuran: 2988,
        juz: 19,
        page: 369,
        arab: "\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u062c\u064e\u0645\u0650\u064a\u0639\u064c \u062d\u064e\u0627\u0630\u0650\u0631\u064f\u0648\u0646\u064e",
        transliteration: "Wa innaa lajamee'un haaziroon",
        translation: "dan sesungguhnya kita semua tanpa kecuali harus selalu waspada.\u201d",
        shortTafsir: "\"Dan sesungguhnya kita semua, tanpa kecuali, harus selalu waspada, mawas diri terhadap segala kemungkinan yang akan terjadi yang diperbuat oleh Musa dan Bani Israil.\" Kemudian Fir\u2019aun bergerak mengejar Nabi Musa dan meninggalkan Mesir.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2988",
      ),
      Ayah(
        numberInSurah: 57,
        numberInQuran: 2989,
        juz: 19,
        page: 369,
        arab: "\u0641\u064e\u0623\u064e\u062e\u0652\u0631\u064e\u062c\u0652\u0646\u064e\u0627\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064d \u0648\u064e\u0639\u064f\u064a\u064f\u0648\u0646\u064d",
        transliteration: "Fa akhrajnaahum min Jannaatinw wa 'uyoon",
        translation: "Kemudian, Kami keluarkan mereka (Fir\u2018aun dan kaumnya) dari taman-taman dan mata air,",
        shortTafsir: "Kemudian, Kami keluarkan mereka, yaitu Fir\u2018aun dan kaumnya, dari taman-taman dan mata air, yang sangat indah yang mereka punyai demi untuk sesuatu tujuan yang batil. Dan Kami keluarkan mereka juga dari harta kekayaan dan kedudukan yang mulia yang mereka dapatkan.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2989",
      ),
      Ayah(
        numberInSurah: 58,
        numberInQuran: 2990,
        juz: 19,
        page: 369,
        arab: "\u0648\u064e\u0643\u064f\u0646\u064f\u0648\u0632\u064d \u0648\u064e\u0645\u064e\u0642\u064e\u0627\u0645\u064d \u0643\u064e\u0631\u0650\u064a\u0645\u064d",
        transliteration: "Wa kunoozinw wa ma qaamin kareem",
        translation: "dan (dari) harta kekayaan dan kedudukan yang mulia,",
        shortTafsir: "Kemudian, Kami keluarkan mereka, yaitu Fir\u2018aun dan kaumnya, dari taman-taman dan mata air, yang sangat indah yang mereka punyai demi untuk sesuatu tujuan yang batil. Dan Kami keluarkan mereka juga dari harta kekayaan dan kedudukan yang mulia yang mereka dapatkan.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2990",
      ),
      Ayah(
        numberInSurah: 59,
        numberInQuran: 2991,
        juz: 19,
        page: 369,
        arab: "\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0648\u064e\u0623\u064e\u0648\u0652\u0631\u064e\u062b\u0652\u0646\u064e\u0627\u0647\u064e\u0627 \u0628\u064e\u0646\u0650\u064a \u0625\u0650\u0633\u0652\u0631\u064e\u0627\u0626\u0650\u064a\u0644\u064e",
        transliteration: "Kazaalika wa awrasnaahaa Baneee Israaa'eel",
        translation: "demikianlah, dan Kami anugerahkan semuanya (itu) kepada Bani Israil.",
        shortTafsir: "Demikianlah, dan Kami anugerahkan semuanya itu kepada Bani Israil. Merekalah pada akhirnya yang mewarisi kekayaan Fir\u2019aun dan peng-ikutnya setelah semuanya binasa.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2991",
      ),
      Ayah(
        numberInSurah: 60,
        numberInQuran: 2992,
        juz: 19,
        page: 369,
        arab: "\u0641\u064e\u0623\u064e\u062a\u0652\u0628\u064e\u0639\u064f\u0648\u0647\u064f\u0645 \u0645\u0651\u064f\u0634\u0652\u0631\u0650\u0642\u0650\u064a\u0646\u064e",
        transliteration: "Fa atba'oohum mushriqeen",
        translation: "Lalu (Fir\u2018aun dan bala tentaranya) dapat menyusul mereka pada waktu matahari terbit.",
        shortTafsir: "Lalu Fir\u2018aun dan bala tentaranya dapat menyusul mereka Musa dan Bani Israil, pada waktu matahari terbit di pagi hari. Kedua kekuatan berada pada jarak yang semakin dekat. Situasi sudah sangat menegangkan.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2992",
      ),
      Ayah(
        numberInSurah: 61,
        numberInQuran: 2993,
        juz: 19,
        page: 370,
        arab: "\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062a\u064e\u0631\u064e\u0627\u0621\u064e\u0649 \u0627\u0644\u0652\u062c\u064e\u0645\u0652\u0639\u064e\u0627\u0646\u0650 \u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064f \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0625\u0650\u0646\u0651\u064e\u0627 \u0644\u064e\u0645\u064f\u062f\u0652\u0631\u064e\u0643\u064f\u0648\u0646\u064e",
        transliteration: "Falammaa taraaa'al jam'aani qaala as haabu Moosaaa innaa lamudrakoon",
        translation: "Maka ketika kedua golongan itu saling melihat, berkatalah pengikut-pengikut Musa, \u201cKita benar-benar akan tersusul.\u201d",
        shortTafsir: "Maka ketika kedua golongan itu saling melihat, berkatalah pengikut-pengikut Musa dengan nada gemetar dan takut \u201cKita benar-benar akan tersusul, oleh Fir\u2019aun dan bala tentaranya.\"",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2993",
      ),
      Ayah(
        numberInSurah: 62,
        numberInQuran: 2994,
        juz: 19,
        page: 370,
        arab: "\u0642\u064e\u0627\u0644\u064e \u0643\u064e\u0644\u0651\u064e\u0627 \u06d6 \u0625\u0650\u0646\u0651\u064e \u0645\u064e\u0639\u0650\u064a\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u0633\u064e\u064a\u064e\u0647\u0652\u062f\u0650\u064a\u0646\u0650",
        transliteration: "Qaala kallaaa inna ma'iya Rabbee sa yahdeen",
        translation: "Dia (Musa) menjawab, \u201cSekali-kali tidak akan (tersusul); sesungguhnya Tuhanku bersamaku, Dia akan memberi petunjuk kepadaku.\u201d",
        shortTafsir: "Dia Musa menjawab dengan tenang dan meyakinkan, \u201cSekali-kali tidak akan tersusul. Sesungguhnya Tuhanku bersamaku, Dia akan memberi petunjuk kepadaku. Tuhanku yang menyuruhku keluar dari Mesir, maka pasti Tuhanku jualah yang akan melindungi kita dengan cara-Nya sendiri.\"",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2994",
      ),
      Ayah(
        numberInSurah: 63,
        numberInQuran: 2995,
        juz: 19,
        page: 370,
        arab: "\u0641\u064e\u0623\u064e\u0648\u0652\u062d\u064e\u064a\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0623\u064e\u0646\u0650 \u0627\u0636\u0652\u0631\u0650\u0628 \u0628\u0651\u0650\u0639\u064e\u0635\u064e\u0627\u0643\u064e \u0627\u0644\u0652\u0628\u064e\u062d\u0652\u0631\u064e \u06d6 \u0641\u064e\u0627\u0646\u0641\u064e\u0644\u064e\u0642\u064e \u0641\u064e\u0643\u064e\u0627\u0646\u064e \u0643\u064f\u0644\u0651\u064f \u0641\u0650\u0631\u0652\u0642\u064d \u0643\u064e\u0627\u0644\u0637\u0651\u064e\u0648\u0652\u062f\u0650 \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u0650",
        transliteration: "Fa awhainaaa ilaa Moosaaa anidrib bi'asaakal bahra fanfalaqa fakaana kullu firqin kattawdil 'azeem",
        translation: "Lalu Kami wahyukan kepada Musa, \u201cPukullah laut itu dengan tongkatmu.\u201d Maka terbelahlah lautan itu, dan setiap belahan seperti gunung yang besar.",
        shortTafsir: "Pada saat genting seperti inilah, Allah memerintahkan kepada Nabi Musa untuk memukulkan tongkatnya ke laut. Allah sebenarnya bisa membelahkan laut tanpa harus ada penyebab berupa pukulan tongkat, tapi Allah ingin agar manusia tetap berusaha. Lalu Kami wahyukan kepada Musa, \u201cPukullah laut itu dengan tongkatmu.\u201d Lalu Nabi Musa memukulkan tongkatnya ke laut, Maka seketika itu, terbelahlah lautan itu menjadi daratan yang bisa dilalui oleh Nabi Musa. Daratan itu terdiri dari dua belas belahan, sesuai dengan kelompok yang ada pada Bani Israil. Dan setiap belahan seperti gunung yang besar.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2995",
      ),
      Ayah(
        numberInSurah: 64,
        numberInQuran: 2996,
        juz: 19,
        page: 370,
        arab: "\u0648\u064e\u0623\u064e\u0632\u0652\u0644\u064e\u0641\u0652\u0646\u064e\u0627 \u062b\u064e\u0645\u0651\u064e \u0627\u0644\u0652\u0622\u062e\u064e\u0631\u0650\u064a\u0646\u064e",
        transliteration: "Wa azlafnaa sammal aakhareen",
        translation: "Dan di sanalah Kami dekatkan golongan yang lain.",
        shortTafsir: "Dan di sanalah Kami dekatkan golongan yang lain, yaitu Fir\u2019aun dan bala tentaranya, sebagai cara Kami sebelum menenggelamkan mereka. Lalu Fir\u2019aun dan bala tentaranya mengejar Nabi Musa melalui jalan yang terbelah itu. Kemudian setelah semuanya berada di tengah laut, Kami kembalikan daratan itu menjadi laut kembali, sehingga Fir\u2019aun dan semua bala tentaranya mati tenggelam.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2996",
      ),
      Ayah(
        numberInSurah: 65,
        numberInQuran: 2997,
        juz: 19,
        page: 370,
        arab: "\u0648\u064e\u0623\u064e\u0646\u062c\u064e\u064a\u0652\u0646\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0648\u064e\u0645\u064e\u0646 \u0645\u0651\u064e\u0639\u064e\u0647\u064f \u0623\u064e\u062c\u0652\u0645\u064e\u0639\u0650\u064a\u0646\u064e",
        transliteration: "Wa anjainaa Moosaa wa mam ma'ahooo ajma'een",
        translation: "Dan Kami selamatkan Musa dan orang-orang yang bersamanya.",
        shortTafsir: "Dan Kami selamatkan Musa dan orang-orang yang bersamanya sebagai balasan atas kesabaran mereka dalam mengahadapi Fir\u2019aun dan kekejamannya, dan atas kesabaran taat kepada ajakan Nabi Musa untuk berhijrah dari negeri Mesir.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2997",
      ),
      Ayah(
        numberInSurah: 66,
        numberInQuran: 2998,
        juz: 19,
        page: 370,
        arab: "\u062b\u064f\u0645\u0651\u064e \u0623\u064e\u063a\u0652\u0631\u064e\u0642\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u0622\u062e\u064e\u0631\u0650\u064a\u0646\u064e",
        transliteration: "Summa aghraqnal aakhareen",
        translation: "Kemudian Kami tenggelamkan golongan yang lain.",
        shortTafsir: "Kemudian Kami tenggelamkan golongan yang lain yaitu Fir\u2019aun dan bala tentaranya, sebagai balasan atas kesombongan dan kekafiran mereka.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2998",
      ),
      Ayah(
        numberInSurah: 67,
        numberInQuran: 2999,
        juz: 19,
        page: 370,
        arab: "\u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0622\u064a\u064e\u0629\u064b \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064f\u0647\u064f\u0645 \u0645\u0651\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",
        transliteration: "Inna fee zaalika la Aayaah; wa maa kaana aksaru hu mu'mineen",
        translation: "Sungguh, pada yang demikian itu terdapat suatu tanda (kekuasaan Allah), tetapi kebanyakan mereka tidak beriman.",
        shortTafsir: "Sungguh, pada yang demikian itu, yaitu binasanya orang yang durhaka dan selamatnya orang yang beriman, terdapat suatu tanda kekuasaan Allah yang demikian besar, tetapi kebanyakan mereka tidak beriman.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2999",
      ),
      Ayah(
        numberInSurah: 68,
        numberInQuran: 3000,
        juz: 19,
        page: 370,
        arab: "\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0644\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f",
        transliteration: "Wa inna Rabbaka la Huwal 'Azeezur Raheem",
        translation: "Dan sesungguhnya Tuhanmu Dialah Yang Mahaperkasa, Maha Penyayang.",
        shortTafsir: "Dan sesungguhnya Tuhanmu Dialah Yang Mahaperkasa Mahakuat atas segala sesuatu, tidak ada yang bisa mengalahkan-Nya, Disisi lain, Dia Maha Penyayang bagi mereka yang beriman dan mau kembali ke jalan Allah.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3000",
      ),
      Ayah(
        numberInSurah: 69,
        numberInQuran: 3001,
        juz: 19,
        page: 370,
        arab: "\u0648\u064e\u0627\u062a\u0652\u0644\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0646\u064e\u0628\u064e\u0623\u064e \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e",
        transliteration: "Watlu 'alaihim naba-a Ibraaheem",
        translation: "Dan bacakanlah kepada mereka kisah Ibrahim.",
        shortTafsir: "Ayat-ayat berikut ini menyebutkan beberapa kisah Nabi Ibrahim ketika menyeru kaumnya untuk mengesakan Allah. Dan bacakanlah kepada mereka, kaum musyrik Mekah, kisah perjuangan Nabi Ibrahim. Kaum musyrik menganggap bahwa mereka adalah penerus agama Nabi Ibrahim dan anaknya Ismail, padahal hal itu sama sekali bertentangan dengan agama Ibrahim yang sebenarnya, yaitu agama tauhid.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3001",
      ),
      Ayah(
        numberInSurah: 70,
        numberInQuran: 3002,
        juz: 19,
        page: 370,
        arab: "\u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u0644\u0650\u0623\u064e\u0628\u0650\u064a\u0647\u0650 \u0648\u064e\u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650 \u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0646\u064e",
        transliteration: "Iz qaala li abeehi wa qawmihee maa ta'budoon",
        translation: "Ketika dia (Ibrahim) berkata kepada ayahnya dan kaumnya, \u201cApakah yang kamu sembah?\u201d",
        shortTafsir: "Ketika dia Ibrahim berkata kepada ayahnya dan kaumnya, yang menyembah berhala di Irak selatan, \u201cApakah yang kamu sembah? bukankah itu benda mati yang dibuat dengan tanganmu sendiri?\"",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3002",
      ),
      Ayah(
        numberInSurah: 71,
        numberInQuran: 3003,
        juz: 19,
        page: 370,
        arab: "\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0646\u064e\u0639\u0652\u0628\u064f\u062f\u064f \u0623\u064e\u0635\u0652\u0646\u064e\u0627\u0645\u064b\u0627 \u0641\u064e\u0646\u064e\u0638\u064e\u0644\u0651\u064f \u0644\u064e\u0647\u064e\u0627 \u0639\u064e\u0627\u0643\u0650\u0641\u0650\u064a\u0646\u064e",
        transliteration: "Qaaloo na'budu asnaaman fanazallu lahaa 'aakifeen",
        translation: "Mereka menjawab, \u201cKami menyembah berhala-berhala dan kami senantiasa tekun menyembahnya.\u201d",
        shortTafsir: "Mereka menjawab, \"Kami menyembah berhala-berhala dan kami senantiasa tekun menyembahnya setiap saat.\" Nabi Ibrahim mencoba berdialog dengan mereka dan mengajak mereka berpikir secara rasional, tidak secara emosional.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3003",
      ),
      Ayah(
        numberInSurah: 72,
        numberInQuran: 3004,
        juz: 19,
        page: 370,
        arab: "\u0642\u064e\u0627\u0644\u064e \u0647\u064e\u0644\u0652 \u064a\u064e\u0633\u0652\u0645\u064e\u0639\u064f\u0648\u0646\u064e\u0643\u064f\u0645\u0652 \u0625\u0650\u0630\u0652 \u062a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e",
        transliteration: "Qaala hal yasma'oona kum iz tad'oon",
        translation: "Dia (Ibrahim) berkata, \u201cApakah mereka mendengarmu ketika kamu berdoa (kepadanya)?",
        shortTafsir: "Ibrahim berkata dalam bentuk kalimat tanya agar mereka mulai berpikir, \u201cApakah mereka, tuhan yang kamu sembah itu, mendengarmu ketika kamu berdoa kepadanya sehingga kamu pantas untuk menyembahnya?\". Alasan seorang menyembah sesuatu adalah dalam rangka mendatangkan kemanfaatan dan menolak bahaya.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3004",
      ),
      Ayah(
        numberInSurah: 73,
        numberInQuran: 3005,
        juz: 19,
        page: 370,
        arab: "\u0623\u064e\u0648\u0652 \u064a\u064e\u0646\u0641\u064e\u0639\u064f\u0648\u0646\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u0648\u0652 \u064a\u064e\u0636\u064f\u0631\u0651\u064f\u0648\u0646\u064e",
        transliteration: "Aw yanfa'oonakum aw yadurroon",
        translation: "Atau (dapatkah) mereka memberi manfaat atau mencelakakan kamu?\u201d",
        shortTafsir: "\"Atau, dapatkah mereka memberi manfaat kepada kamu seperti rezeki, jika kamu menyembahnya atau mencelakakan kamu jika kamu tidak menyembahnya?\" lanjut Nabi Ibrahim",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3005",
      ),
      Ayah(
        numberInSurah: 74,
        numberInQuran: 3006,
        juz: 19,
        page: 370,
        arab: "\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0628\u064e\u0644\u0652 \u0648\u064e\u062c\u064e\u062f\u0652\u0646\u064e\u0627 \u0622\u0628\u064e\u0627\u0621\u064e\u0646\u064e\u0627 \u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u064a\u064e\u0641\u0652\u0639\u064e\u0644\u064f\u0648\u0646\u064e",
        transliteration: "Qaaloo bal wajadnaaa aabaaa 'anaa kazaalika yaf'aloon",
        translation: "Mereka menjawab, \u201cTidak, tetapi kami dapati nenek moyang kami berbuat begitu.\u201d",
        shortTafsir: "Mereka menjawab, \u201cTidak, mereka tidak memberikan kemanfaatkan dan mendatangkan bahaya, tetapi kami dapati nenek moyang kami berbuat begitu.\u201d Mereka berbangga dengan perilaku seperti itu. Inilah bentuk taklid buta, yaitu mengikuti cara beribadah orang lain walaupun hal itu salah.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3006",
      ),
      Ayah(
        numberInSurah: 75,
        numberInQuran: 3007,
        juz: 19,
        page: 370,
        arab: "\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0641\u064e\u0631\u064e\u0623\u064e\u064a\u0652\u062a\u064f\u0645 \u0645\u0651\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0646\u064e",
        transliteration: "Qaala afara 'aitum maa kuntum ta'budoon",
        translation: "Dia (Ibrahim) berkata, \u201cApakah kamu memperhatikan apa yang kamu sembah,",
        shortTafsir: "Ibrahim berkata, \u201cApakah kamu memperhatikan dengan sebenar-benarnya apa yang kamu sembah, apakah hal itu pantas kamu lakukan?",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3007",
      ),
      Ayah(
        numberInSurah: 76,
        numberInQuran: 3008,
        juz: 19,
        page: 370,
        arab: "\u0623\u064e\u0646\u062a\u064f\u0645\u0652 \u0648\u064e\u0622\u0628\u064e\u0627\u0624\u064f\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u0642\u0652\u062f\u064e\u0645\u064f\u0648\u0646\u064e",
        transliteration: "Antum wa aabaaa'ukumul aqdamoon",
        translation: "kamu dan nenek moyang kamu yang terdahulu?",
        shortTafsir: "Kamu dan nenek moyang kamu yang terdahulu?\" Nabi Ibrahim lantas memperlihatkan sikapnya yang tegas dan bernada permusuhan, karena dalam hal keimanan dan ibadah tidak ada kompromi dengan siapa pun.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3008",
      ),
      Ayah(
        numberInSurah: 77,
        numberInQuran: 3009,
        juz: 19,
        page: 370,
        arab: "\u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u062f\u064f\u0648\u0651\u064c \u0644\u0651\u0650\u064a \u0625\u0650\u0644\u0651\u064e\u0627 \u0631\u064e\u0628\u0651\u064e \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",
        transliteration: "Fa innahum 'aduwwwul leee illaa Rabbal 'aalameen",
        translation: "Sesungguhnya mereka (apa yang kamu sembah) itu musuhku, lain halnya Tuhan seluruh alam,",
        shortTafsir: "\"Sesungguhnya mereka, yakni apa yang kamu sembah, itu musuhku, karena mereka adalah setan dalam bentuk berhala lain halnya Tuhan seluruh alam yang banyak sekali memberikan anugerah kepadaku dan kepada kamu sekalian.\" demikian Nabi Ibrahim menyebutkan satu persatu anugerah Tuhannya agar mereka sadar akan kekeliruan mereka dan mengikuti ajakan Nabi Ibrahim.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3009",
      ),
      Ayah(
        numberInSurah: 78,
        numberInQuran: 3010,
        juz: 19,
        page: 370,
        arab: "\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e\u0646\u0650\u064a \u0641\u064e\u0647\u064f\u0648\u064e \u064a\u064e\u0647\u0652\u062f\u0650\u064a\u0646\u0650",
        transliteration: "Allazee khalaqanee fa Huwa yahdeen",
        translation: "(yaitu) Yang telah menciptakan aku, maka Dia yang memberi petunjuk kepadaku,",
        shortTafsir: "Nabi Ibrahim melanjutkan keterangannnya, Dia adalah Zat yang telah menciptakan aku dalam sebaik-baiknya bentuk dan aku diberi kesempatan dalam hidupku untuk menyembah Allah, maka Dia yang memberi petunjuk kepadaku, menuju ke jalan yang benar melalui wahyu yang diberikan kepadaku.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3010",
      ),
      Ayah(
        numberInSurah: 79,
        numberInQuran: 3011,
        juz: 19,
        page: 370,
        arab: "\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0647\u064f\u0648\u064e \u064a\u064f\u0637\u0652\u0639\u0650\u0645\u064f\u0646\u0650\u064a \u0648\u064e\u064a\u064e\u0633\u0652\u0642\u0650\u064a\u0646\u0650",
        transliteration: "Wallazee Huwa yut'imunee wa yasqeen",
        translation: "dan Yang memberi makan dan minum kepadaku;",
        shortTafsir: "Dan Yang memberi makan dan minum kepadaku, melalui rezeki dari air hujan yang menyuburkan tanah sehingga menumbuhkan tumbuh-tumbuhan. Dari situlah aku makan dan minum.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3011",
      ),
      Ayah(
        numberInSurah: 80,
        numberInQuran: 3012,
        juz: 19,
        page: 370,
        arab: "\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0645\u064e\u0631\u0650\u0636\u0652\u062a\u064f \u0641\u064e\u0647\u064f\u0648\u064e \u064a\u064e\u0634\u0652\u0641\u0650\u064a\u0646\u0650",
        transliteration: "Wa izaa mardtu fahuwa yashfeen",
        translation: "dan apabila aku sakit, Dialah yang menyembuhkan aku,",
        shortTafsir: "Dan apabila aku sakit, Dialah pada hakikatnya yang menyembuhkan aku, baik melalui sebab atau tidak.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3012",
      ),
      Ayah(
        numberInSurah: 81,
        numberInQuran: 3013,
        juz: 19,
        page: 370,
        arab: "\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064f\u0645\u0650\u064a\u062a\u064f\u0646\u0650\u064a \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u062d\u0652\u064a\u0650\u064a\u0646\u0650",
        transliteration: "Wallazee yumeetunee summa yuhyeen",
        translation: "dan Yang akan mematikan aku, kemudian akan menghidupkan aku (kembali),",
        shortTafsir: "Dan Yang akan mematikan aku kemudian akan menghidupkan aku kembali, pada hari akhirat nanti. Inilah Tuhan yang patut kamu sembah, karena kekuasaan-Nya yang mutlak.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3013",
      ),
      Ayah(
        numberInSurah: 82,
        numberInQuran: 3014,
        juz: 19,
        page: 370,
        arab: "\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064e\u0637\u0652\u0645\u064e\u0639\u064f \u0623\u064e\u0646 \u064a\u064e\u063a\u0652\u0641\u0650\u0631\u064e \u0644\u0650\u064a \u062e\u064e\u0637\u0650\u064a\u0626\u064e\u062a\u0650\u064a \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u0650",
        transliteration: "Wallazeee atma'u ai yaghfira lee khateee' atee Yawmad Deen",
        translation: "dan Yang sangat kuinginkan akan mengampuni kesalahanku pada hari Kiamat.\u201d",
        shortTafsir: "Dan Yang sangat kuinginkan akan mengampuni kesalahanku pada hari Kiamat,\u201d hari di mana aku harus mempertanggungjawabkan atas semua amalku.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3014",
      ),
      Ayah(
        numberInSurah: 83,
        numberInQuran: 3015,
        juz: 19,
        page: 370,
        arab: "\u0631\u064e\u0628\u0651\u0650 \u0647\u064e\u0628\u0652 \u0644\u0650\u064a \u062d\u064f\u0643\u0652\u0645\u064b\u0627 \u0648\u064e\u0623\u064e\u0644\u0652\u062d\u0650\u0642\u0652\u0646\u0650\u064a \u0628\u0650\u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u0650\u064a\u0646\u064e",
        transliteration: "Rabbi hab lee hukmanw wa alhiqnee bis saaliheen",
        translation: "Ibrahim berdoa), \u201cYa Tuhanku, berikanlah kepadaku ilmu dan masukkanlah aku ke dalam golongan orang-orang yang saleh,",
        shortTafsir: "Nabi Ibrahim lantas berdoa untuk kebaikan dirinya, orang tuanya, dan orang lain, baik di dunia maupun akhirat, \u201cYa Tuhanku, berikanlah kepadaku ilmu yang bermanfaat dan pemahaman terhadap rahasia agama dan masukkanlah aku ke dalam golongan orang-orang yang saleh yang selalu berada pada jalan yang benar.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3015",
      ),
      Ayah(
        numberInSurah: 84,
        numberInQuran: 3016,
        juz: 19,
        page: 371,
        arab: "\u0648\u064e\u0627\u062c\u0652\u0639\u064e\u0644 \u0644\u0651\u0650\u064a \u0644\u0650\u0633\u064e\u0627\u0646\u064e \u0635\u0650\u062f\u0652\u0642\u064d \u0641\u0650\u064a \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u0650\u064a\u0646\u064e",
        transliteration: "Waj'al lee lisaana sidqin fil aakhireen",
        translation: "dan jadikanlah aku buah tutur yang baik bagi orang-orang (yang datang) kemudian,",
        shortTafsir: "Dan jadikanlah aku buah tutur yang baik bagi orang-orang yang datang kemudian, Allah mengabulkan doa Nabi Ibrahim. Namanya tetap bersinar, sikapnya tetap diagungkan, keturunannya adalah para nabi dari Bani Israil yang terakhir adalah Nabi Muhammad Sallall\u00e0hu \u2018alaihi wa sallam.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3016",
      ),
      Ayah(
        numberInSurah: 85,
        numberInQuran: 3017,
        juz: 19,
        page: 371,
        arab: "\u0648\u064e\u0627\u062c\u0652\u0639\u064e\u0644\u0652\u0646\u0650\u064a \u0645\u0650\u0646 \u0648\u064e\u0631\u064e\u062b\u064e\u0629\u0650 \u062c\u064e\u0646\u0651\u064e\u0629\u0650 \u0627\u0644\u0646\u0651\u064e\u0639\u0650\u064a\u0645\u0650",
        transliteration: "Waj'alnee minw warasati Jannnatin Na'eem",
        translation: "dan jadikanlah aku termasuk orang yang mewarisi surga yang penuh kenikmatan,",
        shortTafsir: "\"Dan jadikanlah aku termasuk orang yang mewarisi surga yang penuh kenikmatan yang tiada habis-habisnya, sebagai anugerah yang tak terhingga dari-Mu, ya Allah.\" lanjut doa Nabi Ibrahim",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3017",
      ),
      Ayah(
        numberInSurah: 86,
        numberInQuran: 3018,
        juz: 19,
        page: 371,
        arab: "\u0648\u064e\u0627\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u0650\u0623\u064e\u0628\u0650\u064a \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0636\u0651\u064e\u0627\u0644\u0651\u0650\u064a\u0646\u064e",
        transliteration: "Waghfir li abeee innahoo kaana mind daalleen",
        translation: "dan ampunilah ayahku, sesungguhnya dia termasuk orang yang sesat,",
        shortTafsir: "Nabi Ibrahim adalah seorang yang sangat santun kepada orang tuanya, walaupun kafir. Dia berdoa untuk kebaikan ayahnya.\"Dan ampunilah ayahku, sesungguhnya dia termasuk orang yang sesat, penyembah berhala.\" Namun karena Allah melarang seseorang mendoakan orang kafir yang telah meninggal, Nabi Ibrahim tidak lagi melanjutkan doa untuk ayahnya.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3018",
      ),
      Ayah(
        numberInSurah: 87,
        numberInQuran: 3019,
        juz: 19,
        page: 371,
        arab: "\u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u062e\u0652\u0632\u0650\u0646\u0650\u064a \u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064f\u0628\u0652\u0639\u064e\u062b\u064f\u0648\u0646\u064e",
        transliteration: "Wa laa tukhzinee Yawma yub'asoon",
        translation: "dan janganlah Engkau hinakan aku pada hari mereka dibangkitkan,",
        shortTafsir: "\"Dan janganlah Engkau hinakan aku pada hari mereka dibangkitkan, di hadapan manusia lain bersamaku, tapi tutupilah kesalahanku, hanya Engkau sajalah yang mengetahui keadaanku yang sebenarnya.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3019",
      ),
      Ayah(
        numberInSurah: 88,
        numberInQuran: 3020,
        juz: 19,
        page: 371,
        arab: "\u064a\u064e\u0648\u0652\u0645\u064e \u0644\u064e\u0627 \u064a\u064e\u0646\u0641\u064e\u0639\u064f \u0645\u064e\u0627\u0644\u064c \u0648\u064e\u0644\u064e\u0627 \u0628\u064e\u0646\u064f\u0648\u0646\u064e",
        transliteration: "Yawma laa yanfa'u maalunw wa laa banoon",
        translation: "(yaitu) pada hari (ketika) harta dan anak-anak  tidak berguna,",
        shortTafsir: "yaitu pada hari ketika harta dan anak-anak tidak lagi berguna, untuk menebus semua dosa-dosa yang ada,\" demikian Nabi Ibrahim menutup doanya. Allah tidak membutuhkan semua itu, karena Allah Mahakaya.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3020",
      ),
      Ayah(
        numberInSurah: 89,
        numberInQuran: 3021,
        juz: 19,
        page: 371,
        arab: "\u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0646\u0652 \u0623\u064e\u062a\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0628\u0650\u0642\u064e\u0644\u0652\u0628\u064d \u0633\u064e\u0644\u0650\u064a\u0645\u064d",
        transliteration: "Illaa man atal laaha biqalbin saleem",
        translation: "kecuali orang-orang yang menghadap Allah dengan hati yang bersih,",
        shortTafsir: "Kecuali orang-orang yang menghadap Allah dengan hati yang bersih, yang selamat dari noda dan dosa.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3021",
      ),
      Ayah(
        numberInSurah: 90,
        numberInQuran: 3022,
        juz: 19,
        page: 371,
        arab: "\u0648\u064e\u0623\u064f\u0632\u0652\u0644\u0650\u0641\u064e\u062a\u0650 \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u064f \u0644\u0650\u0644\u0652\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",
        transliteration: "Wa uzlifatil Jannatu lilmuttaqeen",
        translation: "dan surga didekatkan kepada orang-orang yang bertakwa,",
        shortTafsir: "Dan surga didekatkan kepada orang-orang yang bertakwa yang selalu menjaga diri dari kemaksiatan, agar terhindar dari murka Allah. Surga diperlihatkan kepada mereka, sehingga mereka bisa menikmati pemandangan yang sangat indah di dalamnya. Inilah kenikmatan permulaan sebelum mereka masuk ke dalamnya.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3022",
      ),
      Ayah(
        numberInSurah: 91,
        numberInQuran: 3023,
        juz: 19,
        page: 371,
        arab: "\u0648\u064e\u0628\u064f\u0631\u0651\u0650\u0632\u064e\u062a\u0650 \u0627\u0644\u0652\u062c\u064e\u062d\u0650\u064a\u0645\u064f \u0644\u0650\u0644\u0652\u063a\u064e\u0627\u0648\u0650\u064a\u0646\u064e",
        transliteration: "Wa burrizatil Jaheemu lilghaaween",
        translation: "dan neraka Jahim diperlihatkan dengan jelas kepada orang-orang yang sesat,\u201d",
        shortTafsir: "Dan sebaiknya neraka Jahim yang sangat panas dan menakutkan diperlihatkan dengan jelas kepada orang-orang yang memilih jalan sesat,\u201d yaitu jalan kehidupan yang tidak diridai oleh Allah seperti kekafiran dan kesyirikan.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3023",
      ),
      Ayah(
        numberInSurah: 92,
        numberInQuran: 3024,
        juz: 19,
        page: 371,
        arab: "\u0648\u064e\u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u064a\u0652\u0646\u064e \u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0646\u064e",
        transliteration: "Wa qeela lahum aina maa kuntum ta'budoon",
        translation: "dan dikatakan kepada mereka, \u201cDi mana berhala-berhala yang dahulu kamu sembah,",
        shortTafsir: "Dan pada saat itu dikatakan kepada mereka, \u201cDi mana berhala-berhala yang dahulu kamu sembah. Mestinya berhala-berhala itu berada di sini untuk menolongmu dari siksaan api neraka.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3024",
      ),
      Ayah(
        numberInSurah: 93,
        numberInQuran: 3025,
        juz: 19,
        page: 371,
        arab: "\u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0647\u064e\u0644\u0652 \u064a\u064e\u0646\u0635\u064f\u0631\u064f\u0648\u0646\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u0648\u0652 \u064a\u064e\u0646\u062a\u064e\u0635\u0650\u0631\u064f\u0648\u0646\u064e",
        transliteration: "Min doonil laahi hal yansuroonakum aw yantasiroon",
        translation: "selain Allah? Dapatkah mereka menolong kamu atau menolong diri mereka sendiri?\u201d",
        shortTafsir: "Selain Allah? Dapatkah mereka menolong kamu atau menolong diri mereka sendiri?\u201d Mereka sama sekali tidak bisa berbuat apa-apa. Bahkan berhala-berhala itu dan yang menyembahnya akan masuk neraka bersama-sama.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3025",
      ),
      Ayah(
        numberInSurah: 94,
        numberInQuran: 3026,
        juz: 19,
        page: 371,
        arab: "\u0641\u064e\u0643\u064f\u0628\u0652\u0643\u0650\u0628\u064f\u0648\u0627 \u0641\u0650\u064a\u0647\u064e\u0627 \u0647\u064f\u0645\u0652 \u0648\u064e\u0627\u0644\u0652\u063a\u064e\u0627\u0648\u064f\u0648\u0646\u064e",
        transliteration: "Fakubkiboo feehaa hum walghaawoon",
        translation: "Maka mereka (sesembahan itu) dijungkirkan ke dalam neraka bersama orang-orang yang sesat,",
        shortTafsir: "Maka mereka, sesembahan itu, dijungkirkan ke dalam neraka bersama orang-orang yang sesat, berkali-kali.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3026",
      ),
      Ayah(
        numberInSurah: 95,
        numberInQuran: 3027,
        juz: 19,
        page: 371,
        arab: "\u0648\u064e\u062c\u064f\u0646\u064f\u0648\u062f\u064f \u0625\u0650\u0628\u0652\u0644\u0650\u064a\u0633\u064e \u0623\u064e\u062c\u0652\u0645\u064e\u0639\u064f\u0648\u0646\u064e",
        transliteration: "Wa junoodu Ibleesa ajma'oon",
        translation: "dan bala tentara Iblis semuanya.",
        shortTafsir: "Dan juga bala tentara Iblis semuanya. Iblis sebagai penggoda, manusia kafir yang tergoda, dan berhala-berhala yang dijadikan sesembahan, semuanya akan masuk neraka. Semuanya adalah simbol-simbol pengingkaran terhadap Allah. Pada saat mereka di neraka, terjadilah aksi saling menghujat di antara Iblis dan pengikutnya.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3027",
      ),
      Ayah(
        numberInSurah: 96,
        numberInQuran: 3028,
        juz: 19,
        page: 371,
        arab: "\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0648\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u064a\u064e\u062e\u0652\u062a\u064e\u0635\u0650\u0645\u064f\u0648\u0646\u064e",
        transliteration: "Qaaloo wa hum feehaa yakkhtasimoon",
        translation: "Mereka berkata sambil bertengkar di dalamnya (neraka),",
        shortTafsir: "Mereka para penghuni neraka itu berkata sambil bertengkar di dalamnya. Penghuni neraka mengakui atas kesesatannya.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3028",
      ),
      Ayah(
        numberInSurah: 97,
        numberInQuran: 3029,
        juz: 19,
        page: 371,
        arab: "\u062a\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0646 \u0643\u064f\u0646\u0651\u064e\u0627 \u0644\u064e\u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0627\u0644\u064d \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u064d",
        transliteration: "Tallaahi in kunnaa lafee dalaalim mubeen",
        translation: "\u201dDemi Allah, sesungguhnya kita dahulu (di dunia) dalam kesesatan yang nyata,",
        shortTafsir: "Mereka berkata, \"Demi Allah, sesungguhnya kita dahulu di dunia dalam kesesatan yang nyata,\" yaitu memilih jalan kekafiran.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3029",
      ),
      Ayah(
        numberInSurah: 98,
        numberInQuran: 3030,
        juz: 19,
        page: 371,
        arab: "\u0625\u0650\u0630\u0652 \u0646\u064f\u0633\u064e\u0648\u0651\u0650\u064a\u0643\u064f\u0645 \u0628\u0650\u0631\u064e\u0628\u0651\u0650 \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",
        transliteration: "Iz nusawweekum bi Rabbil 'aalameen",
        translation: "karena kita mempersamakan kamu (berhala-berhala) dengan Tuhan seluruh alam.",
        shortTafsir: "Karena kita mempersamakan kamu yaitu berhala-berhala itu, dengan Tuhan seluruh alam.\" Penyamaan Allah pencipta dan pengurus alam seluruh dengan berhala yang tidak mempunyai andil apa-apa dalam kehidupan adalah satu kezaliman yang nyata. Penghuni neraka tahu siapa sebenarnya yang menyesatkan mereka.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3030",
      ),
      Ayah(
        numberInSurah: 99,
        numberInQuran: 3031,
        juz: 19,
        page: 371,
        arab: "\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0636\u064e\u0644\u0651\u064e\u0646\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0652\u0645\u064f\u062c\u0652\u0631\u0650\u0645\u064f\u0648\u0646\u064e",
        transliteration: "Wa maaa adallanaaa illal mujrimoon",
        translation: "Dan tidak ada yang menyesatkan kita kecuali orang-orang yang berdosa.",
        shortTafsir: "\"Dan tidak ada yang menyesatkan kita kecuali orang-orang yang berdosa, yang terdiri dari setan yang berujud jin dan manusia yang tidak henti-hentinya menggoda ke jalan yang sesat.\"",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3031",
      ),
      Ayah(
        numberInSurah: 100,
        numberInQuran: 3032,
        juz: 19,
        page: 371,
        arab: "\u0641\u064e\u0645\u064e\u0627 \u0644\u064e\u0646\u064e\u0627 \u0645\u0650\u0646 \u0634\u064e\u0627\u0641\u0650\u0639\u0650\u064a\u0646\u064e",
        transliteration: "Famaa lanaa min shaa fi'een",
        translation: "Maka sehingga (sekarang) kita tidak mempunyai pemberi syafaat (penolong),",
        shortTafsir: "\"Maka sehingga kita tidak mempunyai pemberi syafaat yaitu penolong, yang dapat menolong kita dari kesusahan saat ini.\"",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3032",
      ),
      Ayah(
        numberInSurah: 101,
        numberInQuran: 3033,
        juz: 19,
        page: 371,
        arab: "\u0648\u064e\u0644\u064e\u0627 \u0635\u064e\u062f\u0650\u064a\u0642\u064d \u062d\u064e\u0645\u0650\u064a\u0645\u064d",
        transliteration: "Wa laa sadeeqin hameem",
        translation: "dan tidak pula mempunyai teman yang akrab,",
        shortTafsir: "\"Dan tidak pula mempunyai teman yang akrab, yang bisa memberikan sedikit pertolongan.\" sesal mereka. Setelah tidak ada lagi yang membantu, mereka lantas menginginkan kembali lagi ke dunia agar bisa melakukan amal saleh.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3033",
      ),
      Ayah(
        numberInSurah: 102,
        numberInQuran: 3034,
        juz: 19,
        page: 371,
        arab: "\u0641\u064e\u0644\u064e\u0648\u0652 \u0623\u064e\u0646\u0651\u064e \u0644\u064e\u0646\u064e\u0627 \u0643\u064e\u0631\u0651\u064e\u0629\u064b \u0641\u064e\u0646\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",
        transliteration: "Falaw anna lanaa karratan fanakoona minal mu'mineen",
        translation: "Maka seandainya kita dapat kembali (ke dunia) niscaya kita menjadi orang-orang yang beriman.\u201d",
        shortTafsir: "\"Maka seandainya kita dapat kembali ke dunia niscaya kita menjadi orang-orang yang beriman, dan beramal saleh.\" demikian mereka mengungkapkanpenyesalannya. Tapi hal itu mustahil mereka dapatkan, karena hidup di dunia cuma sekali.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3034",
      ),
      Ayah(
        numberInSurah: 103,
        numberInQuran: 3035,
        juz: 19,
        page: 371,
        arab: "\u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0622\u064a\u064e\u0629\u064b \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064f\u0647\u064f\u0645 \u0645\u0651\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",
        transliteration: "Inna fee zaalika la Aayatanw wa maa kaana aksaruhum mu'mineen",
        translation: "Sungguh, pada yang demikian itu terdapat tanda (kekuasaan Allah), tetapi kebanyakan mereka tidak beriman.",
        shortTafsir: "Sungguh, pada yang demikian itu yaitu pada kisah Nabi Ibrahim jika direnungkan dengan saksama, terdapat tanda kekuasaan Allah, tetapi kebanyakan mereka tidak beriman.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3035",
      ),
      Ayah(
        numberInSurah: 104,
        numberInQuran: 3036,
        juz: 19,
        page: 371,
        arab: "\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0644\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f",
        transliteration: "Wa inna Rabbaka la Huwal 'Azeezur Raheem",
        translation: "Dan sungguh, Tuhanmu benar-benar Dialah Mahaperkasa, Maha Penyayang.",
        shortTafsir: "Dan sungguh, Tuhanmu benar-benar Dialah Mahaperkasa, yang mampu mempercepat siksa-Nya, Maha Penyayang dengan mengakhirkan siksa sampai di akhirat nanti.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3036",
      ),
      Ayah(
        numberInSurah: 105,
        numberInQuran: 3037,
        juz: 19,
        page: 371,
        arab: "\u0643\u064e\u0630\u0651\u064e\u0628\u064e\u062a\u0652 \u0642\u064e\u0648\u0652\u0645\u064f \u0646\u064f\u0648\u062d\u064d \u0627\u0644\u0652\u0645\u064f\u0631\u0652\u0633\u064e\u0644\u0650\u064a\u0646\u064e",
        transliteration: "Kazzabat qawmu Noohinil Mursaleen",
        translation: "Kaum Nuh telah mendustakan para rasul.",
        shortTafsir: "Kaum Nabi Nuh telah mendustakan para rasul. Para rasul Allah adalah satu kesatuan yang tidak bisa dipisahkan antara satu dengan yang lain. Mendustakan satu rasul sama saja dengan mendustakan semua rasul.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3037",
      ),
      Ayah(
        numberInSurah: 106,
        numberInQuran: 3038,
        juz: 19,
        page: 371,
        arab: "\u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u062e\u064f\u0648\u0647\u064f\u0645\u0652 \u0646\u064f\u0648\u062d\u064c \u0623\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",
        transliteration: "Iz qaala lahum akhoohum Noohun alaa tattaqoon",
        translation: "Ketika saudara mereka (Nuh) berkata kepada mereka, \u201cMengapa kamu tidak bertakwa?",
        shortTafsir: "Ketika saudara mereka yaitu Nabi Nuh, saudara senegeri, berkata kepada mereka, \u201cMengapa kamu tidak bertakwa? Pertanyaan itu terlontar mengingat bahwa mereka adalah penyembah patung-patung Wadd, Suwa\u2019, Yaghuts, Ya'uq, dan Nasr (Lihat: Surah: Nuh: 23).",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3038",
      ),
      Ayah(
        numberInSurah: 107,
        numberInQuran: 3039,
        juz: 19,
        page: 371,
        arab: "\u0625\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u0643\u064f\u0645\u0652 \u0631\u064e\u0633\u064f\u0648\u0644\u064c \u0623\u064e\u0645\u0650\u064a\u0646\u064c",
        transliteration: "Innee lakum Rasoolun ameen",
        translation: "Sesungguhnya aku ini seorang rasul kepercayaan (yang diutus) kepadamu,",
        shortTafsir: "Nabi Nuh melanjutkan dakwahnya, \"Sesungguhnya aku ini seorang rasul kepercayaan yang diutus kepadamu, untuk menyampaikan pesan-pesan Tuhanku kepadamu.\"",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3039",
      ),
      Ayah(
        numberInSurah: 108,
        numberInQuran: 3040,
        juz: 19,
        page: 371,
        arab: "\u0641\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u0650",
        transliteration: "Fattaqullaaha wa atee'oon",
        translation: "Maka bertakwalah kamu kepada Allah dan taatlah kepadaku.",
        shortTafsir: "\"Maka bertakwalah kamu kepada Allah dengan menjaga diri agar tidak mendapat murka Allah dan taatlah kepadaku atas semua yang aku sampaikan kepadamu.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3040",
      ),
      Ayah(
        numberInSurah: 109,
        numberInQuran: 3041,
        juz: 19,
        page: 371,
        arab: "\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0643\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0645\u0650\u0646\u0652 \u0623\u064e\u062c\u0652\u0631\u064d \u06d6 \u0625\u0650\u0646\u0652 \u0623\u064e\u062c\u0652\u0631\u0650\u064a\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650 \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",
        transliteration: "Wa maaa as'alukum 'alaihi min ajrin in ajriya illaa 'alaa Rabbil 'aalameen",
        translation: "Dan aku tidak meminta imbalan kepadamu atas ajakan itu; imbalanku hanyalah dari Tuhan seluruh alam.",
        shortTafsir: "Dan aku tidak meminta imbalan apa pun kepadamu baik berupa materi atau jasa, atas ajakan itu, karena imbalanku hanyalah dari Tuhan seluruh alam yang jauh lebih baik dari semua imbalan yang ada karena Allah Mahakaya, pemilik alam seluruh.\"",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3041",
      ),
      Ayah(
        numberInSurah: 110,
        numberInQuran: 3042,
        juz: 19,
        page: 371,
        arab: "\u0641\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u0650",
        transliteration: "Fattaqul laaha wa atee'oon",
        translation: "Maka bertakwalah kamu kepada Allah dan taatlah kepadaku.\u201d",
        shortTafsir: "\"Maka bertakwalah kamu kepada Allah dengan mengerjakan semua perintahnya dan menjauhi semua larangan-Nya dan taatlah kepadaku, atas semua yang aku sampaikan kepadamu.\" Kaum Nabi Nuh langsung memberikan reaksi secara negatif.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3042",
      ),
      Ayah(
        numberInSurah: 111,
        numberInQuran: 3043,
        juz: 19,
        page: 371,
        arab: "\u06de \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0623\u064e\u0646\u064f\u0624\u0652\u0645\u0650\u0646\u064f \u0644\u064e\u0643\u064e \u0648\u064e\u0627\u062a\u0651\u064e\u0628\u064e\u0639\u064e\u0643\u064e \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0630\u064e\u0644\u064f\u0648\u0646\u064e",
        transliteration: "Qaalooo anu'minu laka wattaba 'akal arzaloon",
        translation: "Mereka berkata, \u201cApakah kami harus beriman kepadamu, padahal pengikut-pengikutmu orang-orang yang hina?\u201d",
        shortTafsir: "Mereka berkata, \u201cApakah kami harus beriman kepadamu, padahal pengikut-pengikutmu orang-orang yang hina?\u201d Pengikut Nabi Nuh banyak dari golongan rakyat jelata, karena merekalah yang banyak terzalimi dari sistem yang ada, bukan dari kalangan bangsawan yang senang dengan kedudukan mereka. Begitulah mereka melihat persoalan bukan dari ajarannya tapi dari orang yang mengikuti ajaran itu.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3043",
      ),
      Ayah(
        numberInSurah: 112,
        numberInQuran: 3044,
        juz: 19,
        page: 372,
        arab: "\u0642\u064e\u0627\u0644\u064e \u0648\u064e\u0645\u064e\u0627 \u0639\u0650\u0644\u0652\u0645\u0650\u064a \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",
        transliteration: "Qaala wa maa 'ilmee bimaa kaanoo ya'maloon",
        translation: "Dia (Nuh) menjawab, \u201cTidak ada pengetahuanku tentang apa yang mereka kerjakan.",
        shortTafsir: "Mendengar ejekan kaumnya, dia, yakni Nabi Nuh, menjawab, \u201cTidak ada pengetahuanku tentang apa yang mereka orang-orang yang hina dina itu kerjakan. Aku hanya mengetahui hal-hal yang lahir saja dari mereka saja.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3044",
      ),
      Ayah(
        numberInSurah: 113,
        numberInQuran: 3045,
        juz: 19,
        page: 372,
        arab: "\u0625\u0650\u0646\u0652 \u062d\u0650\u0633\u064e\u0627\u0628\u064f\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u064a \u06d6 \u0644\u064e\u0648\u0652 \u062a\u064e\u0634\u0652\u0639\u064f\u0631\u064f\u0648\u0646\u064e",
        transliteration: "In hisaabuhum illaa 'alaa Rabbee law tash'uroon",
        translation: "Perhitungan (amal perbuatan) mereka tidak lain hanyalah kepada Tuhanku, jika kamu menyadari.",
        shortTafsir: "Perhitungan amal perbuatan mereka tidak lain hanyalah kepada Tuhanku, karena Tuhanku yang mengetahui secara hakiki niat dari perbuatan mereka, jika kamu menyadari terhadap apa yang aku katakan. Semestinya kamu memahami persoalan ini dengan akal sehatmu.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3045",
      ),
      Ayah(
        numberInSurah: 114,
        numberInQuran: 3046,
        juz: 19,
        page: 372,
        arab: "\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u064e\u0627 \u0628\u0650\u0637\u064e\u0627\u0631\u0650\u062f\u0650 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",
        transliteration: "Wa maaa ana bitaaridil mu'mineen",
        translation: "Dan aku tidak akan mengusir orang-orang yang beriman.",
        shortTafsir: "Lalu dengan lantang Nabi Nuh mengatakan kepada kaumnya tentang pengikut-pengikutnya yang setia. \"Dan aku tidak akan mengusir orang-orang yang beriman. Tidak terkecuali apakah mereka terdiri dari orang-orang miskin, dari kalangan bawah atau lainnya. orang-orang itu pastilah memahami apa yang aku dakwahkan kepada mereka.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3046",
      ),
      Ayah(
        numberInSurah: 115,
        numberInQuran: 3047,
        juz: 19,
        page: 372,
        arab: "\u0625\u0650\u0646\u0652 \u0623\u064e\u0646\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0646\u064e\u0630\u0650\u064a\u0631\u064c \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u064c",
        transliteration: "In ana illaa nazeerum mubeen",
        translation: "Aku (ini) hanyalah pemberi peringatan yang jelas.\u201d",
        shortTafsir: "Aku, Nabi Nuh, ini hanyalah pemberi peringatan yang jelas terhadap mereka yang selalu berdusta kepadaku, bahwa nasib mereka pastilah akan jelek.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3047",
      ),
      Ayah(
        numberInSurah: 116,
        numberInQuran: 3048,
        juz: 19,
        page: 372,
        arab: "\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u064e\u0626\u0650\u0646 \u0644\u0651\u064e\u0645\u0652 \u062a\u064e\u0646\u062a\u064e\u0647\u0650 \u064a\u064e\u0627 \u0646\u064f\u0648\u062d\u064f \u0644\u064e\u062a\u064e\u0643\u064f\u0648\u0646\u064e\u0646\u0651\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064e\u0631\u0652\u062c\u064f\u0648\u0645\u0650\u064a\u0646\u064e",
        transliteration: "Qaaloo la'il lam tantahi yaa Noohu latakoonanna minal marjoomeen",
        translation: "Mereka berkata, \u201cWahai Nuh! Sungguh, jika engkau tidak (mau) berhenti, niscaya engkau termasuk orang yang dirajam (dilempari batu sampai mati).\u201d",
        shortTafsir: "Mendengar jawaban Nabi Nuh yang demikian tegas dan masuk akal, kaumnya mengintimidasinya. Mereka berkata, \u201cWahai Nuh! Sungguh, jika engkau tidak mau berhenti dari ajakanmu, niscaya engkau termasuk orang yang dirajam yaitu dilempari batu sampai mati.\u201d Demikianlah sikap orang-orang zalim pada setiap zaman. Mereka akan menggunakan kekuatan jika kalah dalam adu argumentasi. Mendengar ancaman kaumnya, Nabi Nuh mengadu kepada Tuhannya.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3048",
      ),
      Ayah(
        numberInSurah: 117,
        numberInQuran: 3049,
        juz: 19,
        page: 372,
        arab: "\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0625\u0650\u0646\u0651\u064e \u0642\u064e\u0648\u0652\u0645\u0650\u064a \u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0646\u0650",
        transliteration: "Qaala Rabbi inna qawmee kazzaboon",
        translation: "Dia (Nuh) berkata, \u201cYa Tuhanku, sungguh kaumku telah mendustakan aku;",
        shortTafsir: "Dia, Nabi Nuh, berkata, \u201cYa Tuhanku sungguh kaumku telah mendustakan aku. Mereka telah memilih jalan kesesatan, padahal aku, sesuai dengan perintah-Mu, telah mengajak mereka dengan baik-baik, siang dan malam, selama ratusan tahun, untuk kembali ke jalan-Mu.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3049",
      ),
      Ayah(
        numberInSurah: 118,
        numberInQuran: 3050,
        juz: 19,
        page: 372,
        arab: "\u0641\u064e\u0627\u0641\u0652\u062a\u064e\u062d\u0652 \u0628\u064e\u064a\u0652\u0646\u0650\u064a \u0648\u064e\u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u0641\u064e\u062a\u0652\u062d\u064b\u0627 \u0648\u064e\u0646\u064e\u062c\u0651\u0650\u0646\u0650\u064a \u0648\u064e\u0645\u064e\u0646 \u0645\u0651\u064e\u0639\u0650\u064a\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",
        transliteration: "Faftab bainee wa bai nahum fat hanw wa najjinee wa mam ma'iya minal mu'mineen",
        translation: "maka berilah keputusan antara aku dengan mereka, dan selamatkanlah aku dan mereka yang beriman bersamaku.\u201d",
        shortTafsir: "Maka berilah keputusan antara aku dengan mereka wahai Tuhanku, di Tangan-Mu-lah nasib mereka dan aku memohon kepada-Mu, selamatkanlah aku dan mereka yang beriman bersamaku dari siksaan-Mu yang akan Engkau timpakan kepada kaumku.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3050",
      ),
      Ayah(
        numberInSurah: 119,
        numberInQuran: 3051,
        juz: 19,
        page: 372,
        arab: "\u0641\u064e\u0623\u064e\u0646\u062c\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f \u0648\u064e\u0645\u064e\u0646 \u0645\u0651\u064e\u0639\u064e\u0647\u064f \u0641\u0650\u064a \u0627\u0644\u0652\u0641\u064f\u0644\u0652\u0643\u0650 \u0627\u0644\u0652\u0645\u064e\u0634\u0652\u062d\u064f\u0648\u0646\u0650",
        transliteration: "Fa anjainaahu wa mamma'ahoo fil fulkil mashhoon",
        translation: "Kemudian Kami menyelamatkannya Nuh dan orang-orang yang bersamanya di dalam kapal yang penuh muatan.",
        shortTafsir: "Allah pun mengabulkan doa Nabi Nuh. Kemudian Kami menyelamatkannya yakni Nuh dan orang-orang yang bersamanya di dalam kapal yang penuh muatan yaitu berupa kebutuhan pokok mereka.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3051",
      ),
      Ayah(
        numberInSurah: 120,
        numberInQuran: 3052,
        juz: 19,
        page: 372,
        arab: "\u062b\u064f\u0645\u0651\u064e \u0623\u064e\u063a\u0652\u0631\u064e\u0642\u0652\u0646\u064e\u0627 \u0628\u064e\u0639\u0652\u062f\u064f \u0627\u0644\u0652\u0628\u064e\u0627\u0642\u0650\u064a\u0646\u064e",
        transliteration: "Summa aghraqnaa ba'dul baaqeen",
        translation: "Kemudian setelah itu Kami tenggelamkan orang-orang yang tinggal.",
        shortTafsir: "Kemudian setelah penyelamatan itu, Kami tenggelamkan orang-orang yang tinggal yaitu mereka yang durhaka.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3052",
      ),
      Ayah(
        numberInSurah: 121,
        numberInQuran: 3053,
        juz: 19,
        page: 372,
        arab: "\u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0622\u064a\u064e\u0629\u064b \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064f\u0647\u064f\u0645 \u0645\u0651\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",
        transliteration: "Inna fee zaalika la Aayaah; wa maa kaana aksaruhum mu'mineen",
        translation: "Sungguh, pada yang demikian itu benar-benar terdapat tanda (kekuasaan Allah), tetapi kebanyakan mereka tidak beriman.",
        shortTafsir: "Sungguh, pada kejadian yang demikian itu benar-benar terdapat tanda kekuasaan Allah yang demikian nyata, tetapi kebanyakan mereka tidak beriman.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3053",
      ),
      Ayah(
        numberInSurah: 122,
        numberInQuran: 3054,
        juz: 19,
        page: 372,
        arab: "\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0644\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f",
        transliteration: "Wa inna Rabbaka la huwal 'Azeezur Raheem",
        translation: "Dan sungguh, Tuhanmu, Dialah Yang Mahaperkasa, Maha Penyayang.",
        shortTafsir: "Dan sungguh, Tuhanmu, Dialah Yang Mahaperkasa yang tidak berku-rang kekuasaan-Nya walaupun banyaknya orang yang ingkar kepada-Nya, Maha Penyayang dengan tidak cepat membinasakan orang yang durhaka kepada-Nya, tapi masih memberikan kesempatan kepada mereka untuk bertobat.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3054",
      ),
      Ayah(
        numberInSurah: 123,
        numberInQuran: 3055,
        juz: 19,
        page: 372,
        arab: "\u0643\u064e\u0630\u0651\u064e\u0628\u064e\u062a\u0652 \u0639\u064e\u0627\u062f\u064c \u0627\u0644\u0652\u0645\u064f\u0631\u0652\u0633\u064e\u0644\u0650\u064a\u0646\u064e",
        transliteration: "Kazzabat 'Aadunil mursaleen",
        translation: "(Kaum) \u2018Ad telah mendustakan para rasul.",
        shortTafsir: "Kaum \u2018Ad yang mendiami tanah Yaman telah mendustakan para rasul. Mendustakan satu rasul, sama saja dengan mendustakan seluruh rasul, karena mereka adalah satu kesatuan, yaitu sebagai utusan Allah.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3055",
      ),
      Ayah(
        numberInSurah: 124,
        numberInQuran: 3056,
        juz: 19,
        page: 372,
        arab: "\u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u062e\u064f\u0648\u0647\u064f\u0645\u0652 \u0647\u064f\u0648\u062f\u064c \u0623\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",
        transliteration: "Iz qaala lahum akhoohum Hoodun alaa tattaqoon",
        translation: "Ketika saudara mereka Hud berkata kepada mereka, \u201cMengapa kamu tidak bertakwa?",
        shortTafsir: "Ketika saudara mereka sendiri yang satu negeri dan satu kabilah yaitu Hud berkata kepada mereka dengan tulus ikhlas mengajak mereka ke jalan yang benar, \u201cMengapa kamu tidak bertakwa?\"",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3056",
      ),
      Ayah(
        numberInSurah: 125,
        numberInQuran: 3057,
        juz: 19,
        page: 372,
        arab: "\u0625\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u0643\u064f\u0645\u0652 \u0631\u064e\u0633\u064f\u0648\u0644\u064c \u0623\u064e\u0645\u0650\u064a\u0646\u064c",
        transliteration: "Innee lakum Rasoolun ameen",
        translation: "Sungguh, aku ini seorang rasul kepercayaan (yang diutus) kepadamu,",
        shortTafsir: "\"Sungguh, aku ini seorang rasul kepercayaan Allah yang diutus kepadamu, agar kamu taat kepada-Nya.\"",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3057",
      ),
      Ayah(
        numberInSurah: 126,
        numberInQuran: 3058,
        juz: 19,
        page: 372,
        arab: "\u0641\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u0650",
        transliteration: "Fattaqullaaha wa atee'oon",
        translation: "karena itu bertakwalah kepada Allah dan taatlah kepadaku.",
        shortTafsir: "\"Karena itu bertakwalah kepada Allah dengan menaati semua perintah-Nya dan menjauhi larangan-Nya dan taatlah kepadaku atas apa yang aku katakan kepada kamu.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3058",
      ),
      Ayah(
        numberInSurah: 127,
        numberInQuran: 3059,
        juz: 19,
        page: 372,
        arab: "\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0643\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0645\u0650\u0646\u0652 \u0623\u064e\u062c\u0652\u0631\u064d \u06d6 \u0625\u0650\u0646\u0652 \u0623\u064e\u062c\u0652\u0631\u0650\u064a\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650 \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",
        transliteration: "Wa maa as'alukum 'alaihi min ajrin in ajriya illaa 'alaa Rabbil 'aalameen",
        translation: "Dan aku tidak meminta imbalan kepadamu atas ajakan itu; imbalanku hanyalah dari Tuhan seluruh alam.",
        shortTafsir: "Kemudian agar kaumnya tidak mencurigai missinya sebagai missi yang komersial, Nabi Hud berkata, \"Dan aku tidak meminta imbalan apa pun kepadamu, baik materi maupun jasa atas ajakan itu; karena imbalanku hanyalah dari Tuhan yang mengatur seluruh alam seluruh karena aku adalah utusan-Nya.\"",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3059",
      ),
      Ayah(
        numberInSurah: 128,
        numberInQuran: 3060,
        juz: 19,
        page: 372,
        arab: "\u0623\u064e\u062a\u064e\u0628\u0652\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0643\u064f\u0644\u0651\u0650 \u0631\u0650\u064a\u0639\u064d \u0622\u064a\u064e\u0629\u064b \u062a\u064e\u0639\u0652\u0628\u064e\u062b\u064f\u0648\u0646\u064e",
        transliteration: "Atabnoona bikulli ree'in aayatan ta'basoon",
        translation: "Apakah kamu mendirikan istana-istana pada setiap tanah yang tinggi untuk kemegahan tanpa ditempati,",
        shortTafsir: "Nabi Hud mengecam perilaku buruk kaumnya dan berkata, Apakah kamu mendirikan istana-istana pada setiap tanah yang tinggi hanya untuk kemegahan dan kepongahan tanpa ditempati? Sungguh hal ini keterlaluan.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3060",
      ),
      Ayah(
        numberInSurah: 129,
        numberInQuran: 3061,
        juz: 19,
        page: 372,
        arab: "\u0648\u064e\u062a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0646\u064e \u0645\u064e\u0635\u064e\u0627\u0646\u0650\u0639\u064e \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u062e\u0652\u0644\u064f\u062f\u064f\u0648\u0646\u064e",
        transliteration: "Wa tattakhizoona masaani'a la'allakum takhludoon",
        translation: "dan kamu membuat benteng-benteng dengan harapan kamu hidup kekal?",
        shortTafsir: "Dan kamu membuat benteng-benteng yang kokoh dan kuat, atau penampungan-penampungan air yang besar dengan maksud supaya kamu kekal di dunia?\"",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3061",
      ),
      Ayah(
        numberInSurah: 130,
        numberInQuran: 3062,
        juz: 19,
        page: 372,
        arab: "\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0628\u064e\u0637\u064e\u0634\u0652\u062a\u064f\u0645 \u0628\u064e\u0637\u064e\u0634\u0652\u062a\u064f\u0645\u0652 \u062c\u064e\u0628\u0651\u064e\u0627\u0631\u0650\u064a\u0646\u064e",
        transliteration: "Wa izaa batashtum batashtum jabbaareen",
        translation: "Dan apabila kamu menyiksa, maka kamu lakukan secara kejam dan bengis.",
        shortTafsir: "Dan apabila kamu menyiksa orang-orang yang terkena sanksi hukum dalam pandangan kamu, maka kamu menyiksa sebagai orang-orang kejam dan bengis di luar batas peri kemanusiaan.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3062",
      ),
      Ayah(
        numberInSurah: 131,
        numberInQuran: 3063,
        juz: 19,
        page: 372,
        arab: "\u0641\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u0650",
        transliteration: "Fattaqul laaha wa atee'oon",
        translation: "Maka bertakwalah kepada Allah dan taatlah kepadaku,",
        shortTafsir: "Maka bertakwalah kepada Allah dan taatlah kepadaku. Ketahuilah bahwa apa yang kamu lakukan itu adalah perbuatan yang melanggar hukum-hukum Allah.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3063",
      ),
      Ayah(
        numberInSurah: 132,
        numberInQuran: 3064,
        juz: 19,
        page: 372,
        arab: "\u0648\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0623\u064e\u0645\u064e\u062f\u0651\u064e\u0643\u064f\u0645 \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",
        transliteration: "Wattaqul lazeee amad dakum bimaa ta'lamoon",
        translation: "dan tetaplah kamu bertakwa kepada-Nya yang telah menganugerahkan kepadamu apa yang kamu ketahui.",
        shortTafsir: "Dan bertakwalah kepada Allah yang telah menganugerahkan kepadamu apa yang kamu ketahui dan kamu rasakan, yaitu segala kenikmatan duniawi.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3064",
      ),
      Ayah(
        numberInSurah: 133,
        numberInQuran: 3065,
        juz: 19,
        page: 372,
        arab: "\u0623\u064e\u0645\u064e\u062f\u0651\u064e\u0643\u064f\u0645 \u0628\u0650\u0623\u064e\u0646\u0652\u0639\u064e\u0627\u0645\u064d \u0648\u064e\u0628\u064e\u0646\u0650\u064a\u0646\u064e",
        transliteration: "Amaddakum bi an'aa minw wa baneen",
        translation: "Dia (Allah) telah menganugerahkan kepadamu hewan ternak dan anak-anak,",
        shortTafsir: "Nabi Hud lalu memerinci beberapa kenikmatan itu. Dia telah menganugerahkan dan melimpahkan kepada kamu binatang-binatang ternak yang sangat besar manfaatnya dalam kehidupan kamu dan Dia juga memberimu anak-anak yang dengan mereka kamu merasa kuat.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3065",
      ),
      Ayah(
        numberInSurah: 134,
        numberInQuran: 3066,
        juz: 19,
        page: 372,
        arab: "\u0648\u064e\u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064d \u0648\u064e\u0639\u064f\u064a\u064f\u0648\u0646\u064d",
        transliteration: "Wa jannaatinw wa 'uyoon",
        translation: "dan kebun-kebun, dan mata air,",
        shortTafsir: "Dan kebun-kebun yang rindang, dengan aneka macam tumbuh-tumbuhan dan pepohonan dan mata air yang jernih dan melimpah.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3066",
      ),
      Ayah(
        numberInSurah: 135,
        numberInQuran: 3067,
        juz: 19,
        page: 372,
        arab: "\u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u062e\u064e\u0627\u0641\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u064a\u064e\u0648\u0652\u0645\u064d \u0639\u064e\u0638\u0650\u064a\u0645\u064d",
        transliteration: "Innee akhaafu 'alaikum 'azaaba Yawmin 'azeem",
        translation: "sesungguhnya aku takut kamu akan ditimpa azab pada hari yang besar.\u201d",
        shortTafsir: "Sesungguhnya aku takut kamu akan ditimpa azab hari yang besar, yaitu hari Kiamat. Apa yang kamu miliki dan kamu banggakan, pada hari itu, tidak akan bisa menolong kamu dari siksa api neraka.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3067",
      ),
      Ayah(
        numberInSurah: 136,
        numberInQuran: 3068,
        juz: 19,
        page: 372,
        arab: "\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0633\u064e\u0648\u064e\u0627\u0621\u064c \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0623\u064e\u0648\u064e\u0639\u064e\u0638\u0652\u062a\u064e \u0623\u064e\u0645\u0652 \u0644\u064e\u0645\u0652 \u062a\u064e\u0643\u064f\u0646 \u0645\u0651\u0650\u0646\u064e \u0627\u0644\u0652\u0648\u064e\u0627\u0639\u0650\u0638\u0650\u064a\u0646\u064e",
        transliteration: "Qaaloo sawaaa'un 'alainaaa awa 'azta am lam takum minal waa'izeen",
        translation: "Mereka menjawab, \u201cSama saja bagi kami, apakah engkau memberi nasihat atau tidak memberi nasihat,",
        shortTafsir: "Namun, dengan sikap sombong, kaumnya menolak ajakannya. Mereka menjawab, \"Adalah sama saja bagi Kami, apakah kamu wahai Hud, memberi nasihat atau tidak memberi nasihat, kami tetap tidak akan menuruti ajakanmu. Kami akan terus berpegang teguh dengan keyakinan kami. Maka kamu tak perlu bersusah payah terus menerus mengajak kami.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3068",
      ),
      Ayah(
        numberInSurah: 137,
        numberInQuran: 3069,
        juz: 19,
        page: 373,
        arab: "\u0625\u0650\u0646\u0652 \u0647\u064e\u0670\u0630\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u062e\u064f\u0644\u064f\u0642\u064f \u0627\u0644\u0652\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",
        transliteration: "In haazaaa illaa khuluqul awwaleen",
        translation: "(agama kami) ini tidak lain hanyalah adat kebiasaan orang-orang terdahulu,",
        shortTafsir: "\"Agama kami ini tidak lain hanyalah adat kebiasaan orang dahulu. Apa yang dilakukan nenek moyang kami, itulah yang kami ikuti.\" Inilah bentuk taklid buta dalam hal keyakinan agama yang sangat dibenci oleh Allah.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3069",
      ),
      Ayah(
        numberInSurah: 138,
        numberInQuran: 3070,
        juz: 19,
        page: 373,
        arab: "\u0648\u064e\u0645\u064e\u0627 \u0646\u064e\u062d\u0652\u0646\u064f \u0628\u0650\u0645\u064f\u0639\u064e\u0630\u0651\u064e\u0628\u0650\u064a\u0646\u064e",
        transliteration: "Wa maa nahnu bimu 'azzabeen",
        translation: "dan kami (sama sekali) tidak akan diazab.\u201d",
        shortTafsir: "Dan dengan pongahnya mereka berkata lagi, \"Dan Kami sama sekali tidak akan di azab oleh Allah di akhirat kelak.\" Mereka menganggap bahwa kenikmatan yang mereka miliki adalah bentuk kasih sayang Allah kepada mereka, maka di akhirat pun mereka yakin tidak akan disiksa.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3070",
      ),
      Ayah(
        numberInSurah: 139,
        numberInQuran: 3071,
        juz: 19,
        page: 373,
        arab: "\u0641\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0647\u064f \u0641\u064e\u0623\u064e\u0647\u0652\u0644\u064e\u0643\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u06d7 \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0622\u064a\u064e\u0629\u064b \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064f\u0647\u064f\u0645 \u0645\u0651\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",
        transliteration: "Fakazzaboohu fa ahlaknaahum; inna fee zaalika la aayah; wa maa kaana aksaruhum mu'mineen",
        translation: "Maka mereka mendustakannya (Hud), lalu Kami binasakan mereka. Sungguh, pada yang demikian itu terdapat tanda (kekuasaan Allah), tetapi kebanyakan mereka tidak beriman.",
        shortTafsir: "Sebagai sanksi atas kepongahan mereka, Allah menurunkan siksaNya kepada mereka. Maka mereka mendustakan Hud terhadap semua ajakan dan nasihatnya, lalu Kami binasakan mereka dengan angin yang sangat dingin dan kencang selama tujuh malam dan delapan hari terus menerus (Lihat juga Surah Al-Haqqah/69: 7). Sungguh pada kejadian yang demikian itu terdapat tanda kekuasaan Allah yang demikian besar dan nyata yang semestinya menjadi pelajaran bagi mereka, tetapi kebanyakan mereka tidak beriman bahkan mendustakan Allah dan rasul-Nya.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3071",
      ),
      Ayah(
        numberInSurah: 140,
        numberInQuran: 3072,
        juz: 19,
        page: 373,
        arab: "\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0644\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f",
        transliteration: "Wa inna Rabbaka la huwal 'Azeezur Raheem",
        translation: "Dan sungguh, Tuhanmu, Dialah Yang Mahaperkasa, Maha Penyayang.",
        shortTafsir: "Dan sungguh, Tuhanmu, Dialah Yang Mahaperkasa yang tidak berkurang kekuasaan-Nya dengan banyaknya orang yang ingkar kepada-Nya, Maha Penyayang dengan tidak cepat membinasakan orang yang durhaka kepadaNya, tapi masih memberikan kesempatan kepada mereka untuk bertobat.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3072",
      ),
      Ayah(
        numberInSurah: 141,
        numberInQuran: 3073,
        juz: 19,
        page: 373,
        arab: "\u0643\u064e\u0630\u0651\u064e\u0628\u064e\u062a\u0652 \u062b\u064e\u0645\u064f\u0648\u062f\u064f \u0627\u0644\u0652\u0645\u064f\u0631\u0652\u0633\u064e\u0644\u0650\u064a\u0646\u064e",
        transliteration: "Kazzabat Samoodul mursaleen",
        translation: "Kaum Samud telah mendustakan para rasul.",
        shortTafsir: "Kaum Samud telah mendustakan para rasul yang mengajak mereka kembali kepada jalan yang benar, yaitu menauhidkan Allah, tidak menyekutukan-Nya dengan yang lain dan beribadah kepada-Nya dengan ikhlas.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3073",
      ),
      Ayah(
        numberInSurah: 142,
        numberInQuran: 3074,
        juz: 19,
        page: 373,
        arab: "\u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u062e\u064f\u0648\u0647\u064f\u0645\u0652 \u0635\u064e\u0627\u0644\u0650\u062d\u064c \u0623\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",
        transliteration: "Iz qaala lahum akhoohum Saalihun alaa tattaqoon",
        translation: "Ketika saudara mereka Saleh berkata kepada mereka, \u201cMengapa kamu tidak bertakwa?",
        shortTafsir: "Ketika saudara mereka yang berasal dari negeri dan kabilah mereka sendiri yaitu Saleh berkata kepada mereka dengan maksud menasihati, \"Mengapa kamu tidak bertakwa dengan menjaga diri kamu dari murka Allah, dengan menauhidkan-Nya dan menjalani semua perintahnya?\"",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3074",
      ),
      Ayah(
        numberInSurah: 143,
        numberInQuran: 3075,
        juz: 19,
        page: 373,
        arab: "\u0625\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u0643\u064f\u0645\u0652 \u0631\u064e\u0633\u064f\u0648\u0644\u064c \u0623\u064e\u0645\u0650\u064a\u0646\u064c",
        transliteration: "Innee lakum Rasoolun ameen",
        translation: "Sungguh, aku ini seorang rasul kepercayaan (yang diutus) kepadamu,",
        shortTafsir: "\"Sesungguhnya aku adalah seorang rasul kepercayaan Allah yang diutus kepadamu, untuk mengingatkanmu akan jalan kebenaran untuk kebaikanmu juga.\"",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3075",
      ),
      Ayah(
        numberInSurah: 144,
        numberInQuran: 3076,
        juz: 19,
        page: 373,
        arab: "\u0641\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u0650",
        transliteration: "Fattaqul laaha wa atee'oon",
        translation: "karena itu bertakwalah kepada Allah dan taatlah kepadaku.",
        shortTafsir: "Karena itu, bertakwalah kepada Allah dan taatlah kepadaku terhadap apa yang aku perintahkan dan yang aku larang kepadamu.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3076",
      ),
      Ayah(
        numberInSurah: 145,
        numberInQuran: 3077,
        juz: 19,
        page: 373,
        arab: "\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0643\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0645\u0650\u0646\u0652 \u0623\u064e\u062c\u0652\u0631\u064d \u06d6 \u0625\u0650\u0646\u0652 \u0623\u064e\u062c\u0652\u0631\u0650\u064a\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650 \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",
        transliteration: "Wa maaa as'alukum 'alaihi min ajrin in ajriya illaa 'alaa Rabbil 'aalameen",
        translation: "Dan aku tidak meminta sesuatu imbalan kepadamu atas ajakan itu, imbalanku hanyalah dari Tuhan seluruh alam.",
        shortTafsir: "Dan aku tidak meminta suatu imbalan kepadamu atas ajakan itu, baik berupa materi atau non materi. Imbalanku tidak lain hanyalah dari Tuhan Pemelihara seluruh alam. Dialah yang mengutusku.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3077",
      ),
      Ayah(
        numberInSurah: 146,
        numberInQuran: 3078,
        juz: 19,
        page: 373,
        arab: "\u0623\u064e\u062a\u064f\u062a\u0652\u0631\u064e\u0643\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0645\u064e\u0627 \u0647\u064e\u0627\u0647\u064f\u0646\u064e\u0627 \u0622\u0645\u0650\u0646\u0650\u064a\u0646\u064e",
        transliteration: "Atutrakoona fee maa haahunnaaa aamineen",
        translation: "Apakah kamu (mengira) akan dibiarkan tinggal di sini (di negeri kamu ini) dengan aman,",
        shortTafsir: "Apakah kamu mengira akan dibiarkan tinggal di sini di negeri kamu ini dengan segala kenikmatannya, dengan aman, tanpa harus bertanggung jawab terhadap Tuhan yang menciptakan kamu?",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3078",
      ),
      Ayah(
        numberInSurah: 147,
        numberInQuran: 3079,
        juz: 19,
        page: 373,
        arab: "\u0641\u0650\u064a \u062c\u064e\u0646\u0651\u064e\u0627\u062a\u064d \u0648\u064e\u0639\u064f\u064a\u064f\u0648\u0646\u064d",
        transliteration: "Fee jannaatinw wa 'uyoon",
        translation: "di dalam kebun-kebun dan mata air,",
        shortTafsir: "Di dalam kebun-kebun yang rindang serta mata air yang jernih dan melimpah,",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3079",
      ),
      Ayah(
        numberInSurah: 148,
        numberInQuran: 3080,
        juz: 19,
        page: 373,
        arab: "\u0648\u064e\u0632\u064f\u0631\u064f\u0648\u0639\u064d \u0648\u064e\u0646\u064e\u062e\u0652\u0644\u064d \u0637\u064e\u0644\u0652\u0639\u064f\u0647\u064e\u0627 \u0647\u064e\u0636\u0650\u064a\u0645\u064c",
        transliteration: "Wa zuroo inw wa nakhlin tal 'uhaa hadeem",
        translation: "dan tanaman-tanaman dan pohon-pohon kurma yang mayangnya lembut.",
        shortTafsir: "dan tanaman-tanaman dan pohon-pohon kurma yang mayangnya lembut yang akan menghasilkan buah kurma yang enak dan lezat.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3080",
      ),
      Ayah(
        numberInSurah: 149,
        numberInQuran: 3081,
        juz: 19,
        page: 373,
        arab: "\u0648\u064e\u062a\u064e\u0646\u0652\u062d\u0650\u062a\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062c\u0650\u0628\u064e\u0627\u0644\u0650 \u0628\u064f\u064a\u064f\u0648\u062a\u064b\u0627 \u0641\u064e\u0627\u0631\u0650\u0647\u0650\u064a\u0646\u064e",
        transliteration: "Wa tanhitoona minal jibaali buyootan faariheen",
        translation: "Dan kamu pahat dengan terampil sebagian gunung-gunung untuk dijadikan rumah-rumah;",
        shortTafsir: "dan kamu pahat dengan terampil sebagian gunung-gunung batu yang demikian besar untuk dijadikan rumah-rumah dengan rajin dan kepiawaian; tapi semua itu kamu lakukan dengan penuh kesombongan dan kepongahan, bukan untuk kemanfaatan semata.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3081",
      ),
      Ayah(
        numberInSurah: 150,
        numberInQuran: 3082,
        juz: 19,
        page: 373,
        arab: "\u0641\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u0650",
        transliteration: "Fattaqul laaha wa atee'oon",
        translation: "maka bertakwalah kepada Allah dan taatlah kepadaku;",
        shortTafsir: "Maka bertakwalah kepada Allah dengan melaksanakan perintah-Nya dan menjauhi semua larangan-Nya dan taatlah kepadaku terhadap apa yang aku sampaikan kepadamu, karena aku adalah utusan Allah;",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3082",
      ),
      Ayah(
        numberInSurah: 151,
        numberInQuran: 3083,
        juz: 19,
        page: 373,
        arab: "\u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0637\u0650\u064a\u0639\u064f\u0648\u0627 \u0623\u064e\u0645\u0652\u0631\u064e \u0627\u0644\u0652\u0645\u064f\u0633\u0652\u0631\u0650\u0641\u0650\u064a\u0646\u064e",
        transliteration: "Wa laa tutee'ooo amral musrifeen",
        translation: "dan janganlah kamu menaati perintah orang-orang yang melampaui batas,",
        shortTafsir: "Dan janganlah kamu menaati perintah orang-orang yang melampaui batas,",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3083",
      ),
      Ayah(
        numberInSurah: 152,
        numberInQuran: 3084,
        juz: 19,
        page: 373,
        arab: "\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0641\u0652\u0633\u0650\u062f\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0635\u0652\u0644\u0650\u062d\u064f\u0648\u0646\u064e",
        transliteration: "Allazeena yufsidoona fil ardi wa laa yuslihoon",
        translation: "yang berbuat kerusakan di bumi dan tidak mengadakan perbaikan.\u201d",
        shortTafsir: "Mereka adalah para pemuka masyarakatmu yang kafir, sombong, berbuat kerusakan, keonaran, dan kemaksiatan di muka bumi dan mereka sama sekali tidak mengadakan perbaikan dalam kehidupan mereka.\" Mereka yang dimaksud Nabi Saleh berjumlah 9 orang (lihat surah an-Naml/27:48) dan tinggal dikawasan antara Madinah dan Yordania yang disebut dengan negeri Mada'in tempat tinggal kaum Samud.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3084",
      ),
      Ayah(
        numberInSurah: 153,
        numberInQuran: 3085,
        juz: 19,
        page: 373,
        arab: "\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u062a\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0633\u064e\u062d\u0651\u064e\u0631\u0650\u064a\u0646\u064e",
        transliteration: "Qaalooo innamaa anta minal musahhareen",
        translation: "Mereka berkata, \u201cSungguh, engkau hanyalah termasuk orang yang kena sihir;",
        shortTafsir: "Akan tetapi mereka menolak dakwah Nabi Saleh dengan berkata, \"Sungguh, engkau hanyalah termasuk orang yang kena sihir, karena apa yang engkau dakwahkan tidak sesuai dengan kebiiasaan kami.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3085",
      ),
      Ayah(
        numberInSurah: 154,
        numberInQuran: 3086,
        juz: 19,
        page: 373,
        arab: "\u0645\u064e\u0627 \u0623\u064e\u0646\u062a\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u064e\u0634\u064e\u0631\u064c \u0645\u0651\u0650\u062b\u0652\u0644\u064f\u0646\u064e\u0627 \u0641\u064e\u0623\u0652\u062a\u0650 \u0628\u0650\u0622\u064a\u064e\u0629\u064d \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u062f\u0650\u0642\u0650\u064a\u0646\u064e",
        transliteration: "Maaa anta illaa basharum mislunaa faati bi Aayatin in kunta minas saadiqeen",
        translation: "engkau hanyalah manusia seperti kami; maka datangkanlah sesuatu mukjizat jika engkau termasuk orang yang benar.\u201d",
        shortTafsir: "Engkau wahai Saleh, tidak lain hanyalah seorang manusia biasa seperti kami; makan, minum, dan lain-lainnya. Mengapa hanya engkau yang diberi wahyu? Maka, oleh karena itu, datangkanlah sesuatu mukjizat, kejadian yang luar biasa jika engkau memang termasuk orang-orang yang benar\u201d, bahwa kamu adalah utusan Allah.\"",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3086",
      ),
      Ayah(
        numberInSurah: 155,
        numberInQuran: 3087,
        juz: 19,
        page: 373,
        arab: "\u0642\u064e\u0627\u0644\u064e \u0647\u064e\u0670\u0630\u0650\u0647\u0650 \u0646\u064e\u0627\u0642\u064e\u0629\u064c \u0644\u0651\u064e\u0647\u064e\u0627 \u0634\u0650\u0631\u0652\u0628\u064c \u0648\u064e\u0644\u064e\u0643\u064f\u0645\u0652 \u0634\u0650\u0631\u0652\u0628\u064f \u064a\u064e\u0648\u0652\u0645\u064d \u0645\u0651\u064e\u0639\u0652\u0644\u064f\u0648\u0645\u064d",
        transliteration: "Qaala haazihee naaqatul lahaa shirbunw w alakum shirbu yawmim ma'loom",
        translation: "Dia (Saleh) menjawab, \u201cIni seekor unta betina, yang berhak mendapatkan (giliran) minum, dan kamu juga berhak mendapatkan minum pada hari yang ditentukan.",
        shortTafsir: "Kemudian Nabi Saleh meminta kepada Allah agar diturunkan tanda-tanda kebesaran-Nya sebagaimana yang dimintakan oleh kaum-nya. Lalu Allah memenuhi permintaan Nabi Saleh dengan keluarnya seekor unta dari batu-batu besar yang ada di sekeliling mereka. Nabi Shaleh menjelaskan, \u201cIni seekor unta betina, sebagai pertanda kebenaran kenabianku seperti apa yang kamu inginkan, dengan dua ketentuan. Pertama, Dia berhak mendapatkan giliran untuk mendapatkan air minum pada satu hari, dan kamu mempunyai giliran pula untuk mendapatkan air di hari yang tertentu, secara bergiliran.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3087",
      ),
      Ayah(
        numberInSurah: 156,
        numberInQuran: 3088,
        juz: 19,
        page: 373,
        arab: "\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0645\u064e\u0633\u0651\u064f\u0648\u0647\u064e\u0627 \u0628\u0650\u0633\u064f\u0648\u0621\u064d \u0641\u064e\u064a\u064e\u0623\u0652\u062e\u064f\u0630\u064e\u0643\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064f \u064a\u064e\u0648\u0652\u0645\u064d \u0639\u064e\u0638\u0650\u064a\u0645\u064d",
        transliteration: "Wa laa tamassoohaa bisooo'in fa yaakhuzakum 'azaabu Yawmin 'Azeem",
        translation: "Dan jangan kamu menyentuhnya (unta itu) dengan sesuatu kejahatan, nanti kamu akan ditimpa azab pada hari yang dahsyat.\u201d",
        shortTafsir: "Dan, ketentuan kedua, janganlah kamu sentuh unta betina itu dengan sesuatu kejahatan, baik dengan memukulnya apalagi membunuhnya, hal yang menyebabkan kamu akan ditimpa azab hari yang besar.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3088",
      ),
      Ayah(
        numberInSurah: 157,
        numberInQuran: 3089,
        juz: 19,
        page: 373,
        arab: "\u0641\u064e\u0639\u064e\u0642\u064e\u0631\u064f\u0648\u0647\u064e\u0627 \u0641\u064e\u0623\u064e\u0635\u0652\u0628\u064e\u062d\u064f\u0648\u0627 \u0646\u064e\u0627\u062f\u0650\u0645\u0650\u064a\u0646\u064e",
        transliteration: "Fa'aqaroohaa fa asbahoo naadimeen",
        translation: "Kemudian mereka membunuhnya, lalu mereka merasa menyesal,",
        shortTafsir: "Ternyata mereka melanggar ketentuan ini. Kemudian salah seorang di antara mereka membunuhnya, sementara yang lain mendiamkannya saja, sebagai tanda persetujuan. Dengan persetujuan ini semuanya dianggap ikut terlibat dalam pembunuhan itu. Lalu mereka merasa menyesal atas apa yang telah mereka lakukan, karena mereka tahu akan akibat dari perbuatan mereka yaitu datangnya siksaan Allah. Tapi tak berguna lagi penyesalan itu. Mereka diberi tenggat waktu sampai tiga hari, (Lihat: Surah Hud/11: 65) lalu datanglah azab yang mereka takutkan.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3089",
      ),
      Ayah(
        numberInSurah: 158,
        numberInQuran: 3090,
        juz: 19,
        page: 373,
        arab: "\u0641\u064e\u0623\u064e\u062e\u064e\u0630\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064f \u06d7 \u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0622\u064a\u064e\u0629\u064b \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064f\u0647\u064f\u0645 \u0645\u0651\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",
        transliteration: "Fa akhazahumul 'azaab; inna fee zaalika la Aayah; wa maa kaana aksaruhum m'mineen",
        translation: "maka mereka ditimpa azab. Sungguh, pada yang demikian itu terdapat tanda (kekuasaan Allah), tetapi kebanyakan mereka tidak beriman.",
        shortTafsir: "Maka mereka ditimpa azab. yaitu suara yang menggelegar disertai dengan guncangan bumi yang dahsyat (lihat: Surah H\u00f9d/11:67) dan (al-H\u00e0qqah/69: 4). Mereka semua mati bergelimpangan, kecuali nabi Saleh dan orang-orang yang beriman kepadanya. Sungguh, pada yang demikian itu, terdapat tanda yang nyata atas kemahakuasaan Allah dan bahwa janji dan ancaman Allah itu benar adanya. Tetapi kebanyakan mereka tidak beriman, hati mereka terkunci mati oleh kesombongan mereka.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3090",
      ),
      Ayah(
        numberInSurah: 159,
        numberInQuran: 3091,
        juz: 19,
        page: 373,
        arab: "\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0644\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f",
        transliteration: "Wa inna Rabbaka la Huwal 'Azeezur Raheem",
        translation: "Dan sungguh, Tuhanmu, Dialah Yang Mahaperkasa, Maha Penyayang.",
        shortTafsir: "Dan Sungguh Tuhanmu, Dialah yang Maha Perkasa, yang tidak ada yang mampu mengalahkan-Nya, Banyaknya orang yang ingkar kepada-Nya tidak mengurangi sedikit pun kekuasaan-Nya. Dia juga Maha Penyayang yang masih memberikan kesempatan kepada yang berdurhaka untuk kembali bertobat.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3091",
      ),
      Ayah(
        numberInSurah: 160,
        numberInQuran: 3092,
        juz: 19,
        page: 374,
        arab: "\u0643\u064e\u0630\u0651\u064e\u0628\u064e\u062a\u0652 \u0642\u064e\u0648\u0652\u0645\u064f \u0644\u064f\u0648\u0637\u064d \u0627\u0644\u0652\u0645\u064f\u0631\u0652\u0633\u064e\u0644\u0650\u064a\u0646\u064e",
        transliteration: "kazzabat qawmu Lootinil mursaleen",
        translation: "Kaum Lut telah mendustakan para rasul,",
        shortTafsir: "Nabi Luth adalah keponakan Nabi Ibrahim. Kaumnya mendiami negeri Sodom, di dataran rendah Yordania. Mereka melakukan kejahatan seksual yaitu sodomi. Kaum Luth telah mendustakan para rasul. Setiap rasul dan penggiat kebenaran pasti mendapatkan tantangan dari banyak pihak. Nabi Luth menyeru kaumnya untuk kembali ke jalan yang benar.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3092",
      ),
      Ayah(
        numberInSurah: 161,
        numberInQuran: 3093,
        juz: 19,
        page: 374,
        arab: "\u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u062e\u064f\u0648\u0647\u064f\u0645\u0652 \u0644\u064f\u0648\u0637\u064c \u0623\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",
        transliteration: "Iz qaala lahum akhoohum Lootun alaa tattaqoon",
        translation: "ketika saudara mereka Lut berkata kepada mereka, \u201cMengapa kamu tidak bertakwa?\u201d",
        shortTafsir: "Ketika saudara mereka yang satu negeri dengan mereka, yaitu Nabi Luth, berkata kepada mereka, \"Mengapa kamu tidak bertakwa?\u201d dengan bertakwa kamu akan selamat baik di dunia maupun di akhirat.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3093",
      ),
      Ayah(
        numberInSurah: 162,
        numberInQuran: 3094,
        juz: 19,
        page: 374,
        arab: "\u0625\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u0643\u064f\u0645\u0652 \u0631\u064e\u0633\u064f\u0648\u0644\u064c \u0623\u064e\u0645\u0650\u064a\u0646\u064c",
        transliteration: "Innee lakum rasoolun ameen",
        translation: "Sungguh, aku ini seorang rasul kepercayaan (yang diutus) kepadamu,",
        shortTafsir: "Sungguh, aku ini seorang rasul kepercayaan yang diutus kepadamu untuk membawa misi kebenaran dari Tuhan Yang mengutusku.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3094",
      ),
      Ayah(
        numberInSurah: 163,
        numberInQuran: 3095,
        juz: 19,
        page: 374,
        arab: "\u0641\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u0650",
        transliteration: "Fattaqul laaha wa atee'oon",
        translation: "maka bertakwalah kepada Allah dan taatlah kepadaku.",
        shortTafsir: "Maka bertakwalah kepada Allah dengan menjalankan semua perintah-Nya dan menjauhi segala larangan-Nya. dan taatlah kepadaku. Atas apa yang aku katakan padamu.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3095",
      ),
      Ayah(
        numberInSurah: 164,
        numberInQuran: 3096,
        juz: 19,
        page: 374,
        arab: "\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0643\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0645\u0650\u0646\u0652 \u0623\u064e\u062c\u0652\u0631\u064d \u06d6 \u0625\u0650\u0646\u0652 \u0623\u064e\u062c\u0652\u0631\u0650\u064a\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650 \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",
        transliteration: "Wa maaa as'alukum 'alaihi min ajrin in ajriya illaa 'alaa Rabbil 'aalameen",
        translation: "Dan aku tidak meminta imbalan kepadamu atas ajakan itu; imbalanku hanyalah dari Tuhan seluruh alam.",
        shortTafsir: "Dan aku sekali-kali tidak minta imbalan kepadamu atas ajakan itu, imbalanku tidak lain hanyalah dari Tuhan pemelihara seluruh alam yang menjadikan aku sebagai utusan-Nya.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3096",
      ),
      Ayah(
        numberInSurah: 165,
        numberInQuran: 3097,
        juz: 19,
        page: 374,
        arab: "\u0623\u064e\u062a\u064e\u0623\u0652\u062a\u064f\u0648\u0646\u064e \u0627\u0644\u0630\u0651\u064f\u0643\u0652\u0631\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",
        transliteration: "Ataatoonaz zukraana minal 'aalameen",
        translation: "Mengapa kamu mendatangi jenis laki-laki di antara manusia (berbuat homoseks),",
        shortTafsir: "Setelah berdakwah setelah umum, Nabi Luth kemudian memasuki area dakwah yang lebih khusus lagi, \"Mengapa kamu mendatangi atau melakukan hubungan seksual dengan laki-laki di antara manusia. Sungguh ini merupakan perbuatan yang sangat keji yang dimurkai Allah.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3097",
      ),
      Ayah(
        numberInSurah: 166,
        numberInQuran: 3098,
        juz: 19,
        page: 374,
        arab: "\u0648\u064e\u062a\u064e\u0630\u064e\u0631\u064f\u0648\u0646\u064e \u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u0652 \u0623\u064e\u0632\u0652\u0648\u064e\u0627\u062c\u0650\u0643\u064f\u0645 \u06da \u0628\u064e\u0644\u0652 \u0623\u064e\u0646\u062a\u064f\u0645\u0652 \u0642\u064e\u0648\u0652\u0645\u064c \u0639\u064e\u0627\u062f\u064f\u0648\u0646\u064e",
        transliteration: "Wa tazaroona maa khalaqa lakum Rabbukum min azwaajikum; bal antum qawmun 'aadoon",
        translation: "dan kamu tinggalkan (perempuan) yang diciptakan Tuhan untuk menjadi istri-istri kamu? Kamu (memang) orang-orang yang melampaui batas.\u201d",
        shortTafsir: "Dan kamu tinggalkan perempuan yang diciptakan oleh Tuhan untuk menjadi istri-istrimu? Terhadap merekalah kamu semaikan bibit keturunanmu kelak, untuk menjadi generasi yang saleh yang memakmurkan bumi. Kamu memang orang-orang yang melampaui batas. Karena melakukan sesuatu bukan pada peruntukannya.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3098",
      ),
      Ayah(
        numberInSurah: 167,
        numberInQuran: 3099,
        juz: 19,
        page: 374,
        arab: "\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u064e\u0626\u0650\u0646 \u0644\u0651\u064e\u0645\u0652 \u062a\u064e\u0646\u062a\u064e\u0647\u0650 \u064a\u064e\u0627 \u0644\u064f\u0648\u0637\u064f \u0644\u064e\u062a\u064e\u0643\u064f\u0648\u0646\u064e\u0646\u0651\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u062e\u0652\u0631\u064e\u062c\u0650\u064a\u0646\u064e",
        transliteration: "Qaloo la'il lam tantahi yaa Lootu latakoonanna minal mukhrajeen",
        translation: "Mereka menjawab, \u201cWahai Lut! Jika engkau tidak berhenti, engkau termasuk orang-orang yang terusir.\u201d",
        shortTafsir: "Namun dengan angkuh mereka menjawab: \"Wahai Luth, jika engkau tidak berhenti dari apa yang engkau lakukan, engkau termasuk orang-orang yang terusir dari negeri ini, karena kami tidak menghendaki engkau berada bersama kami.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3099",
      ),
      Ayah(
        numberInSurah: 168,
        numberInQuran: 3100,
        juz: 19,
        page: 374,
        arab: "\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u0644\u0650\u0639\u064e\u0645\u064e\u0644\u0650\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0627\u0644\u0652\u0642\u064e\u0627\u0644\u0650\u064a\u0646\u064e",
        transliteration: "Qaala innee li'amalikum minal qaaleen",
        translation: "Dia (Lut) berkata, \u201cAku sungguh benci kepada perbuatanmu.\u201d",
        shortTafsir: "Dia, Lut, berkata, \"Aku sungguh benci kepada perbuatanmu karena bertentangan dengan fitrah manusia, hanya mengumbar nafsu seksual belaka yang bukan pada tempatnya.\"",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3100",
      ),
      Ayah(
        numberInSurah: 169,
        numberInQuran: 3101,
        juz: 19,
        page: 374,
        arab: "\u0631\u064e\u0628\u0651\u0650 \u0646\u064e\u062c\u0651\u0650\u0646\u0650\u064a \u0648\u064e\u0623\u064e\u0647\u0652\u0644\u0650\u064a \u0645\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",
        transliteration: "Rabbi najjjinee wa ahlee mimmmaa ya'maloon",
        translation: "(Lut berdoa), \u201cYa Tuhanku, selamatkanlah aku dan keluargaku dari (akibat) perbuatan yang mereka kerjakan.\u201d",
        shortTafsir: "Melihat sikap kaumnya yang tidak berubah bahkan menjadi-jadi, Nabi Lut memohon keselamatan dari Allah dengan berdoa, \"Ya Tuhanku selamatkanlah aku dan keluargaku dan pengikutku yang beriman dari akibat perbuatan yang mereka kerjakan.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3101",
      ),
      Ayah(
        numberInSurah: 170,
        numberInQuran: 3102,
        juz: 19,
        page: 374,
        arab: "\u0641\u064e\u0646\u064e\u062c\u0651\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f \u0648\u064e\u0623\u064e\u0647\u0652\u0644\u064e\u0647\u064f \u0623\u064e\u062c\u0652\u0645\u064e\u0639\u0650\u064a\u0646\u064e",
        transliteration: "Fanajjainaahu wa ahlahooo ajma'een",
        translation: "Lalu Kami selamatkan dia bersama keluarganya semua,",
        shortTafsir: "Lalu Kami selamatkan dia bersama keluarganya semua,",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3102",
      ),
      Ayah(
        numberInSurah: 171,
        numberInQuran: 3103,
        juz: 19,
        page: 374,
        arab: "\u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u064e\u062c\u064f\u0648\u0632\u064b\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u063a\u064e\u0627\u0628\u0650\u0631\u0650\u064a\u0646\u064e",
        transliteration: "Illaa 'ajoozan filghaabireen",
        translation: "kecuali seorang perempuan tua (istrinya), yang termasuk dalam golongan yang tinggal.",
        shortTafsir: "kecuali seorang perempuan tua yaitu istrinya sendiri, yang termasuk dalam golongan yang tinggal. Dia berkhianat terhadap suaminya, dan bergabung dengan kaumnya yang kafir dan lacur.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3103",
      ),
      Ayah(
        numberInSurah: 172,
        numberInQuran: 3104,
        juz: 19,
        page: 374,
        arab: "\u062b\u064f\u0645\u0651\u064e \u062f\u064e\u0645\u0651\u064e\u0631\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u0622\u062e\u064e\u0631\u0650\u064a\u0646\u064e",
        transliteration: "Summa dammarnal aa khareen",
        translation: "Kemudian Kami binasakan yang lain.",
        shortTafsir: "Kemudian Kami binasakan yang lain dan menghancurkan mereka sehancur-hancurnya.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3104",
      ),
      Ayah(
        numberInSurah: 173,
        numberInQuran: 3105,
        juz: 19,
        page: 374,
        arab: "\u0648\u064e\u0623\u064e\u0645\u0652\u0637\u064e\u0631\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645 \u0645\u0651\u064e\u0637\u064e\u0631\u064b\u0627 \u06d6 \u0641\u064e\u0633\u064e\u0627\u0621\u064e \u0645\u064e\u0637\u064e\u0631\u064f \u0627\u0644\u0652\u0645\u064f\u0646\u0630\u064e\u0631\u0650\u064a\u0646\u064e",
        transliteration: "Wa amtarnaa 'alaihim mataran fasaaa'a matarul munzareen",
        translation: "Dan Kami hujani mereka (dengan hujan batu), maka betapa buruk hujan yang menimpa orang-orang yang telah diberi peringatan itu.",
        shortTafsir: "Dan setelah negeri mereka dijungkirbalikkan, Kami hujani mereka dengan hujan batu yang demikian keras. Maka betapa buruk hujan yang menimpa orang-orang yang telah diberi peringatan itu. inilah kesudahan dari kaum yang durhaka kepada Allah. Mereka diberi peringatan demi peringatan namun mereka tetap memilih jalan kehidupan yang keji yang dibenci oleh Allah.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3105",
      ),
      Ayah(
        numberInSurah: 174,
        numberInQuran: 3106,
        juz: 19,
        page: 374,
        arab: "\u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0622\u064a\u064e\u0629\u064b \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064f\u0647\u064f\u0645 \u0645\u0651\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",
        transliteration: "Inna fee zaalika la Aayah; wa maa kaana aksaruhum mu'mineen",
        translation: "Sungguh, pada yang demikian itu terdapat tanda (kekuasaan Allah), tetapi kebanyakan mereka tidak beriman.",
        shortTafsir: "Sungguh pada yang demikian itu benar-benar terdapat bukti-bukti yang nyata akan ke Maha Kuasanya Allah. Dan adalah kebanyakan mereka tidak beriman. Mereka yang ingkar terkena laknat, dan yang yang beriman akan selamat. Inilah ketetapan Allah yang tidak pernah berubah.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3106",
      ),
      Ayah(
        numberInSurah: 175,
        numberInQuran: 3107,
        juz: 19,
        page: 374,
        arab: "\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0644\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f",
        transliteration: "Wa inna Rabbaka la Huwal 'Azeezur Raheem",
        translation: "Dan sungguh, Tuhanmu, Dialah Yang Mahaperkasa, Maha Penyayang.",
        shortTafsir: "Dan sungguh Tuhanmu, yang memeliharamu, benar-benar Dialah Yang Mahaperkasa, Maha Penyayang dengan tidak cepat-cepat menghukum para pendosa, tapi memberikan kesempatan kepada mereka untuk bertobat.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3107",
      ),
      Ayah(
        numberInSurah: 176,
        numberInQuran: 3108,
        juz: 19,
        page: 374,
        arab: "\u0643\u064e\u0630\u0651\u064e\u0628\u064e \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064f \u0627\u0644\u0652\u0623\u064e\u064a\u0652\u0643\u064e\u0629\u0650 \u0627\u0644\u0652\u0645\u064f\u0631\u0652\u0633\u064e\u0644\u0650\u064a\u0646\u064e",
        transliteration: "Kazzaba As haabul Aykatil mursaleen",
        translation: "Penduduk Aikah telah mendustakan para rasul;",
        shortTafsir: "Penduduk Aikah telah mendustakan para rasul; yaitu Nabi Syuaib yang diutus kepada mereka, untuk memperbaiki akidah dan akhlak mereka,",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3108",
      ),
      Ayah(
        numberInSurah: 177,
        numberInQuran: 3109,
        juz: 19,
        page: 374,
        arab: "\u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0634\u064f\u0639\u064e\u064a\u0652\u0628\u064c \u0623\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e",
        transliteration: "Iz qaala lahum Shu'aybun alaa tattaqoon",
        translation: "ketika Syuaib berkata kepada mereka, \u201cMengapa kamu tidak bertakwa?",
        shortTafsir: "Nabi Syuaib memulai dakwahnya dengan berpesan kepada kaumnya untuk bertakwa. Ketika Syuaib berkata kepada mereka, \"Mengapa kamu tidak bertakwa?\" Bertakwa adalah pokok pangkal kebaikan segala sesuatu. Inilah anjuran pertama para rasul sebelum masuk pada materi dakwah lainnya kepada kaumnya. Nabi Syuaib memperkenalkan dirinya dan kedudukannya selaku utusan Allah.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3109",
      ),
      Ayah(
        numberInSurah: 178,
        numberInQuran: 3110,
        juz: 19,
        page: 374,
        arab: "\u0625\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u0643\u064f\u0645\u0652 \u0631\u064e\u0633\u064f\u0648\u0644\u064c \u0623\u064e\u0645\u0650\u064a\u0646\u064c",
        transliteration: "Innee lakum Rasoolun ameen",
        translation: "Sungguh, aku adalah rasul kepercayaan (yang diutus) kepadamu,",
        shortTafsir: "Nabi Syuaib melanjutkan dakwahnya, \"Sungguh, aku adalah rasul kepercayaan Allah yang diutus kepadamu.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3110",
      ),
      Ayah(
        numberInSurah: 179,
        numberInQuran: 3111,
        juz: 19,
        page: 374,
        arab: "\u0641\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0623\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u0650",
        transliteration: "Fattaqul laaha wa atee'oon",
        translation: "maka bertakwalah kepada Allah dan taatlah kepadaku;",
        shortTafsir: "Maka, bertakwalah kepada Allah dan taatlah kepada perintah dan ajakan-ku untuk beribadah kepada Allah dan melakukan kebaikan.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3111",
      ),
      Ayah(
        numberInSurah: 180,
        numberInQuran: 3112,
        juz: 19,
        page: 374,
        arab: "\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0643\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0645\u0650\u0646\u0652 \u0623\u064e\u062c\u0652\u0631\u064d \u06d6 \u0625\u0650\u0646\u0652 \u0623\u064e\u062c\u0652\u0631\u0650\u064a\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650 \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",
        transliteration: "Wa maaa as'alukum 'alaihi min ajrin in ajriya illaa 'alaa Rabbil 'aalameen",
        translation: "Dan aku tidak meminta imbalan kepadamu atas ajakan itu; imbalanku hanyalah dari Tuhan seluruh alam.",
        shortTafsir: "Dan aku tidak bermaksud sedikitpun untuk meminta imbalan apa pun baik berupa materi atau jasa, kepadamu atas ajakan itu, imbalanku tidak lain hanyalah dari Tuhan seluruh alam. Dengan tidak adanya imbalan, Nabi Syuaib tidak mempunyai kepentingan apa-apa kecuali untuk kemaslahatan mereka.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3112",
      ),
      Ayah(
        numberInSurah: 181,
        numberInQuran: 3113,
        juz: 19,
        page: 374,
        arab: "\u06de \u0623\u064e\u0648\u0652\u0641\u064f\u0648\u0627 \u0627\u0644\u0652\u0643\u064e\u064a\u0652\u0644\u064e \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u062e\u0652\u0633\u0650\u0631\u0650\u064a\u0646\u064e",
        transliteration: "Awful kaila wa laa takoonoo minal mukhsireen",
        translation: "Sempurnakanlah takaran dan janganlah kamu merugikan orang lain.",
        shortTafsir: "Kemudian Nabi Syuaib mulai memasuki wilayah dakwah yang lebih nyata lagi yaitu kejahatan ekonomi yang dilakukan kaumnya. \"Sempurnakanlah takaran dan janganlah kamu merugikan orang lain\". Mengurangi takaran dan timbangan sangat merugikan konsumen. Memakan hasilnya hukumnya haram dan tidak membawa berkah dalam kehidupan.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3113",
      ),
      Ayah(
        numberInSurah: 182,
        numberInQuran: 3114,
        juz: 19,
        page: 374,
        arab: "\u0648\u064e\u0632\u0650\u0646\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0652\u0642\u0650\u0633\u0652\u0637\u064e\u0627\u0633\u0650 \u0627\u0644\u0652\u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0650\u064a\u0645\u0650",
        transliteration: "Wa zinoo bilqistaasil mustaqeem",
        translation: "Dan timbanglah dengan timbangan yang benar.",
        shortTafsir: "Dan timbanglah dengan timbangan yang benar, yaitu timbangan yang adil, sesuai dengan yang menjadi kesepakatan masyarakat luas. Hal ini akan menjadikan keberkahan bagimu, wahai para penjual, karena memakan dari harta yang halal.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3114",
      ),
      Ayah(
        numberInSurah: 183,
        numberInQuran: 3115,
        juz: 19,
        page: 374,
        arab: "\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0628\u0652\u062e\u064e\u0633\u064f\u0648\u0627 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064e \u0623\u064e\u0634\u0652\u064a\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u062b\u064e\u0648\u0652\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0645\u064f\u0641\u0652\u0633\u0650\u062f\u0650\u064a\u0646\u064e",
        transliteration: "Wa laa tabkhasun naasa ashyaaa 'ahum wa laa ta'saw fil ardi mufsideen",
        translation: "Dan janganlah kamu merugikan manusia dengan mengurangi hak-haknya dan janganlah membuat kerusakan di bumi;",
        shortTafsir: "Dan janganlah kamu merugikan manusia pada hak-haknya dan jangan-lah kamu membuat kerusakan di bumi. Pada dasarnya prinsip hubungan antar manusia menurut Islam adalah tidak boleh menzalimi dan tidak boleh dizalimi dengan cara apa pun dan dalam bidang apa pun.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3115",
      ),
      Ayah(
        numberInSurah: 184,
        numberInQuran: 3116,
        juz: 19,
        page: 375,
        arab: "\u0648\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0627\u0644\u0652\u062c\u0650\u0628\u0650\u0644\u0651\u064e\u0629\u064e \u0627\u0644\u0652\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",
        transliteration: "Wattaqul lazee khalaqakum waljibillatal awwaleen",
        translation: "dan bertakwalah kepada Allah yang telah menciptakan kamu dan umat-umat yang terdahulu.\u201d",
        shortTafsir: "Nabi Syuaib menutup penjelasannya dengan berkata, \"Dan bertakwalah kepada Allah yang telah menciptakan kamu dan umat-umat yang dahulu\". Umat terdahulu dari kaum Syuaib seperti kaum \u2018Ad, dan \u0160amud jauh lebih kuat. mereka dibinasakan oleh Allah karena dosa-dosa mereka.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3116",
      ),
      Ayah(
        numberInSurah: 185,
        numberInQuran: 3117,
        juz: 19,
        page: 375,
        arab: "\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u062a\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0633\u064e\u062d\u0651\u064e\u0631\u0650\u064a\u0646\u064e",
        transliteration: "Qaalooo innamaa anta minal musahhareen",
        translation: "Mereka berkata, \u201cEngkau tidak lain hanyalah orang-orang yang kena sihir.",
        shortTafsir: "Terhadap ajakan Nabi Syuaib, mereka mulai berang dan jengkel, lalu mereka mengeluarkan tuduhan dan hasutan yang tidak berdasar. Mereka berkata: \"Engkau tidak lain hanyalah orang yang kena sihir\". Semua nabi yang berdakwah kepada kaumnya dituduh sebagai pesihir sebagai cara untuk menjauhkan para nabi dengan masyarakat.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3117",
      ),
      Ayah(
        numberInSurah: 186,
        numberInQuran: 3118,
        juz: 19,
        page: 375,
        arab: "\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u062a\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u064e\u0634\u064e\u0631\u064c \u0645\u0651\u0650\u062b\u0652\u0644\u064f\u0646\u064e\u0627 \u0648\u064e\u0625\u0650\u0646 \u0646\u0651\u064e\u0638\u064f\u0646\u0651\u064f\u0643\u064e \u0644\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0643\u064e\u0627\u0630\u0650\u0628\u0650\u064a\u0646\u064e",
        transliteration: "Wa maaa anta illaa basharum mislunaa wa innazunnuka laminal kaazibeen",
        translation: "Dan engkau hanyalah manusia seperti kami, dan sesungguhnya kami yakin engkau termasuk orang-orang yang berdusta.",
        shortTafsir: "\"Dan engkau hanyalah manusia seperti kami, yang makan dan minum. Apa keistimewaanmu sehingga engkau menjadi seorang utusan Tuhan? Sesungguhnya kami yakin bahwa engkau benar-benar termasuk orang-orang yang berdusta, tuduh mereka. Inilah usaha untuk mematikan gerak dakwah Nabi Syuaib.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3118",
      ),
      Ayah(
        numberInSurah: 187,
        numberInQuran: 3119,
        juz: 19,
        page: 375,
        arab: "\u0641\u064e\u0623\u064e\u0633\u0652\u0642\u0650\u0637\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0643\u0650\u0633\u064e\u0641\u064b\u0627 \u0645\u0651\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u062f\u0650\u0642\u0650\u064a\u0646\u064e",
        transliteration: "Fa asqit 'alainaa kisafam minas samaaa'i in kunta minas saadiqeen",
        translation: "Maka jatuhkanlah kepada kami gumpalan dari langit, jika engkau termasuk orang-orang yang benar.\u201d",
        shortTafsir: "Mereka dengan pongahnya balik menantang Nabi Syuaib agar bisa mendatangkan siksaan kepada mereka. Maka cepat jatuhkanlah siksaan Tuhanmu kepada kami berupa gumpalan apa saja dari langit, baik berupa batu atau lainnya, jika engkau termasuk orang-orang yang benar bahwa engkau adalah utusan Allah.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3119",
      ),
      Ayah(
        numberInSurah: 188,
        numberInQuran: 3120,
        juz: 19,
        page: 375,
        arab: "\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",
        transliteration: "Qaala Rabbeee a'lamu bimaa ta'maloon",
        translation: "Dia (Syuaib) berkata, \u201cTuhanku lebih mengetahui apa yang kamu kerjakan.\u201d",
        shortTafsir: "Nabi Syuaib berkata, \"Tuhanku lebih mengetahui apa yang kamu kerjakan.\" Biarlah Dia saja yang akan membuat perhitungan dengan kamu, karena Dialah yang mengetahui sepak terjangmu.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3120",
      ),
      Ayah(
        numberInSurah: 189,
        numberInQuran: 3121,
        juz: 19,
        page: 375,
        arab: "\u0641\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0647\u064f \u0641\u064e\u0623\u064e\u062e\u064e\u0630\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064f \u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0638\u0651\u064f\u0644\u0651\u064e\u0629\u0650 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0630\u064e\u0627\u0628\u064e \u064a\u064e\u0648\u0652\u0645\u064d \u0639\u064e\u0638\u0650\u064a\u0645\u064d",
        transliteration: "Fakazzaboohu fa akhazahum 'azaabu Yawmiz zullah; innahoo kaana 'azaaba Yawmin 'Azeem",
        translation: "Kemudian mereka mendustakannya (Syuaib), lalu mereka ditimpa azab pada hari yang gelap. Sungguh, itulah azab pada hari yang dahsyat.",
        shortTafsir: "Kemudian mereka mendustakan apa yang disampaikan Nabi Syuaib, lalu tidak berapa lama, mereka ditimpa azab pada hari yang gelap. karena ditutupi awan. Dengan awan ini mereka menganggap bahwa mereka telah selamat, tapi secara mengejutkan mereka dihujani dengan api yang besar dari langit. Sungguh, azab itulah azab pada hari yang dahsyat. Peristiwa yang memilukan itu semestinya menjadi pelajaran bagi semua pihak.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3121",
      ),
      Ayah(
        numberInSurah: 190,
        numberInQuran: 3122,
        juz: 19,
        page: 375,
        arab: "\u0625\u0650\u0646\u0651\u064e \u0641\u0650\u064a \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0622\u064a\u064e\u0629\u064b \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064f\u0647\u064f\u0645 \u0645\u0651\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",
        transliteration: "Inna fee zaalika la Aayah; wa maa kaana aksaruhum mu'mineen",
        translation: "Sungguh, pada yang demikian itu benar-benar terdapat tanda (kekuasaan Allah), tetapi kebanyakan mereka tidak beriman.",
        shortTafsir: "Sungguh, pada kejadian yang demikian itu benar-benar terdapat tanda kekuasaan Allah, tetapi kebanyakan mereka tidak beriman, karena hati mereka sudah tertutup oleh kekafiran, keangkuhan dan kesombongan.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3122",
      ),
      Ayah(
        numberInSurah: 191,
        numberInQuran: 3123,
        juz: 19,
        page: 375,
        arab: "\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0644\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u064f \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f",
        transliteration: "Wa inna Rabbaka la huwal 'Azeezur Raheem",
        translation: "Dan sungguh, Tuhanmu, Dialah yang Mahaperkasa, Maha Penyayang.",
        shortTafsir: "Dan sungguh, Tuhanmu, Dialah yang Maha Perkasa. Tidak ada yang bisa mengalahkan-Nya dan tidak terkurangi sedikit pun kekuasaan-Nya dengan banyaknya orang yang kafir kepada-Nya. Dia juga Maha Penyayang.yang masih memberikan kesempatan bagi orang yang berdosa untuk bertobat kepada-Nya.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3123",
      ),
      Ayah(
        numberInSurah: 192,
        numberInQuran: 3124,
        juz: 19,
        page: 375,
        arab: "\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u062a\u064e\u0646\u0632\u0650\u064a\u0644\u064f \u0631\u064e\u0628\u0651\u0650 \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",
        transliteration: "Wa innahoo latanzeelu Rabbil 'aalameen",
        translation: "Dan sungguh, (Al-Qur'an) ini benar-benar diturunkan oleh Tuhan seluruh alam,",
        shortTafsir: "Dan sungguh Al-Qur'an ini benar-benar diturunkan oleh Tuhan pemilik dan pemelihara seluruh alam, Tuhan yang sangat menyayangi makhluk-Nya, Al-Qur'an tidak berasal dari selain Allah, sebagaimana yang dituduhkan kaum musyrik, itu bukan untuk mencelakakan mereka.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3124",
      ),
      Ayah(
        numberInSurah: 193,
        numberInQuran: 3125,
        juz: 19,
        page: 375,
        arab: "\u0646\u064e\u0632\u064e\u0644\u064e \u0628\u0650\u0647\u0650 \u0627\u0644\u0631\u0651\u064f\u0648\u062d\u064f \u0627\u0644\u0652\u0623\u064e\u0645\u0650\u064a\u0646\u064f",
        transliteration: "Nazala bihir Roohul Ameen",
        translation: "Yang dibawa turun oleh ar-Ruh al-Amin (Jibril),",
        shortTafsir: "Al-Qur\u2019an itu dibawa turun secara berangsur-angsur oleh Ar-Ruh Al-Amin yaitu Jibril, atas izin Allah. Ruh adalah sesuatu yang dengannya raga menjadi hidup, begitu juga Al-Qur\u2019an.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3125",
      ),
      Ayah(
        numberInSurah: 194,
        numberInQuran: 3126,
        juz: 19,
        page: 375,
        arab: "\u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064e\u0644\u0652\u0628\u0650\u0643\u064e \u0644\u0650\u062a\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0646\u0630\u0650\u0631\u0650\u064a\u0646\u064e",
        transliteration: "'Alaa qalbika litakoona minal munzireen",
        translation: "ke dalam hatimu (Muhammad) agar engkau termasuk orang yang memberi peringatan,",
        shortTafsir: "Jibril langsung memasukkan Al-Qur\u2019an ke dalam hatimu, wahai Nabi Muhmmad, yang dengan itu Al-Qur\u2019an terpelihara. Tujuannya agar engkau termasuk orang yang memberi peringatan kepada manusia agar mawas diri. Jika mereka memilih kekafiran dan kefasikan, setelah datangnya penjelasan, mereka akan diberi sanksi yang berat oleh Allah.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3126",
      ),
      Ayah(
        numberInSurah: 195,
        numberInQuran: 3127,
        juz: 19,
        page: 375,
        arab: "\u0628\u0650\u0644\u0650\u0633\u064e\u0627\u0646\u064d \u0639\u064e\u0631\u064e\u0628\u0650\u064a\u0651\u064d \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u064d",
        transliteration: "Bilisaanin 'Arabiyyim mubeen",
        translation: "dengan bahasa Arab yang jelas.",
        shortTafsir: "Al-Qur'an yang diturunkan kepadamu, dan penjelasanmu tentangnya itu dengan bahasa Arab yang jelas. dengan demikian, bisa dengan mudah dipahami oleh masyarakat Arab, di mana Al-Qur\u2019an turun pertama kali kepada mereka.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3127",
      ),
      Ayah(
        numberInSurah: 196,
        numberInQuran: 3128,
        juz: 19,
        page: 375,
        arab: "\u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0641\u0650\u064a \u0632\u064f\u0628\u064f\u0631\u0650 \u0627\u0644\u0652\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",
        transliteration: "Wa innahoo lafee Zuburil awwaleen",
        translation: "Dan sungguh, (Al-Qur'an) itu (disebut) dalam kitab-kitab orang yang terdahulu.",
        shortTafsir: "Dan sungguh, Al-Qur'an itu benar-benar disebut dalam kitab-kitab orang yang dahulu seperti Taurat, Zabur, dan Injil (Lihat: Surah al-A\u2019raf/7: 157). Hal ini menunjukkan akan satunya tujuan, satunya sumber, dan keterkaitan antara satu kitab suci dengan kitab suci lainnya sama-sama menyeru kepada Tauhid.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3128",
      ),
      Ayah(
        numberInSurah: 197,
        numberInQuran: 3129,
        juz: 19,
        page: 375,
        arab: "\u0623\u064e\u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0643\u064f\u0646 \u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u0622\u064a\u064e\u0629\u064b \u0623\u064e\u0646 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064e\u0647\u064f \u0639\u064f\u0644\u064e\u0645\u064e\u0627\u0621\u064f \u0628\u064e\u0646\u0650\u064a \u0625\u0650\u0633\u0652\u0631\u064e\u0627\u0626\u0650\u064a\u0644\u064e",
        transliteration: "Awalam yakul lahum Aayatan ai ya'lamahoo 'ulamaaa'u Baneee Israaa'eel",
        translation: "Apakah tidak (cukup) menjadi bukti bagi mereka, bahwa para ulama Bani Israil mengetahuinya?",
        shortTafsir: "Dukungan terhadap kebenaran Al-Qur\u2019an juga datang dari para ulama Bani Israil. Apakah tidak cukup menjadi bukti bagi mereka, bahwa para ulama Bani Israil mengetahuinya? Mereka, dahulu, bahkan sangat menantikan kedatangan Nabi Muhammad.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3129",
      ),
      Ayah(
        numberInSurah: 198,
        numberInQuran: 3130,
        juz: 19,
        page: 375,
        arab: "\u0648\u064e\u0644\u064e\u0648\u0652 \u0646\u064e\u0632\u0651\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0628\u064e\u0639\u0652\u0636\u0650 \u0627\u0644\u0652\u0623\u064e\u0639\u0652\u062c\u064e\u0645\u0650\u064a\u0646\u064e",
        transliteration: "Wa law nazzalnaahu 'alaa ba'dil a'jameen",
        translation: "Dan seandainya (Al-Qur'an) itu Kami turunkan kepada sebagian dari golongan bukan Arab,",
        shortTafsir: "Dan seandainya Al-Qur'an itu Kami turunkan kepada sebagian dari golongan bukan Arab yang tidak bisa berbicara menggunakan bahasa Arab,",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3130",
      ),
      Ayah(
        numberInSurah: 199,
        numberInQuran: 3131,
        juz: 19,
        page: 375,
        arab: "\u0641\u064e\u0642\u064e\u0631\u064e\u0623\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645 \u0645\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0628\u0650\u0647\u0650 \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",
        transliteration: "Faqara ahoo 'alaihim maa kaanoo bihee mu'mineen",
        translation: "lalu dia membacakannya kepada mereka (orang-orang kafir); niscaya mereka tidak juga akan beriman kepadanya.",
        shortTafsir: "lalu ia membacakannya kepada mereka, yakni orang-orang kafir itu, niscaya mereka tidak juga akan beriman kepadanya. Ini menunjukkan keengganan mereka untuk menerima Al-Qur\u2019an. Dari arah mana pun Al-Qur\u2019an itu datang, mereka pasti tak akan beriman dengan berbagai alasan.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3131",
      ),
      Ayah(
        numberInSurah: 200,
        numberInQuran: 3132,
        juz: 19,
        page: 375,
        arab: "\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0633\u064e\u0644\u064e\u0643\u0652\u0646\u064e\u0627\u0647\u064f \u0641\u0650\u064a \u0642\u064f\u0644\u064f\u0648\u0628\u0650 \u0627\u0644\u0652\u0645\u064f\u062c\u0652\u0631\u0650\u0645\u0650\u064a\u0646\u064e",
        transliteration: "Kazaalika salaknaahu fee quloobil mujrimeen",
        translation: "Demikianlah, Kami masukkan (sifat dusta dan ingkar) ke dalam hati orang-orang yang berdosa,",
        shortTafsir: "Demikianlah, sebagaimana Kami memasukkan rasa dusta terhadap Al-Qur\u2019an pada hati orang kafir, Kami masukkan sifat dusta dan ingkar terhadap Al-Qur'an itu ke dalam hati orang- orang yang berdosa.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3132",
      ),
      Ayah(
        numberInSurah: 201,
        numberInQuran: 3133,
        juz: 19,
        page: 375,
        arab: "\u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u0650 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u0631\u064e\u0648\u064f\u0627 \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u0627\u0644\u0652\u0623\u064e\u0644\u0650\u064a\u0645\u064e",
        transliteration: "Laa yu'minoona bihee hattaa yarawul 'azaabal aleem",
        translation: "mereka tidak akan beriman kepadanya, hingga mereka melihat azab yang pedih,",
        shortTafsir: "Mereka tidak juga akan beriman kepadanya, yakni Al-Qur\u2019an, hingga mereka melihat azab yang pedih.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3133",
      ),
      Ayah(
        numberInSurah: 202,
        numberInQuran: 3134,
        juz: 19,
        page: 375,
        arab: "\u0641\u064e\u064a\u064e\u0623\u0652\u062a\u0650\u064a\u064e\u0647\u064f\u0645 \u0628\u064e\u063a\u0652\u062a\u064e\u0629\u064b \u0648\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0634\u0652\u0639\u064f\u0631\u064f\u0648\u0646\u064e",
        transliteration: "Fayaatiyahum baghtatanw wa hum laa yash'uroon",
        translation: "maka datang azab kepada mereka secara mendadak, ketika mereka tidak menyadarinya,",
        shortTafsir: "Maka, pada saat\u00a0 datang azab kepada mereka secara mendadak dan tiba-tiba, ketika mereka tidak menyadarinya, pada saat itulah mereka tersadar akan kesalahan mereka.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3134",
      ),
      Ayah(
        numberInSurah: 203,
        numberInQuran: 3135,
        juz: 19,
        page: 375,
        arab: "\u0641\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627 \u0647\u064e\u0644\u0652 \u0646\u064e\u062d\u0652\u0646\u064f \u0645\u064f\u0646\u0638\u064e\u0631\u064f\u0648\u0646\u064e",
        transliteration: "Fa yaqooloo hal nahnu munzaroon",
        translation: "lalu mereka berkata, \u201cApakah kami diberi penangguhan waktu?\u201d",
        shortTafsir: "Lalu mereka berkata, \"Apakah kami diberi penangguhan waktu, yakni perpanjangan umur kami, sehingga kami bisa bertobat, beriman kepada Al-Qur\u2019an dan melakukan amal saleh?",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3135",
      ),
      Ayah(
        numberInSurah: 204,
        numberInQuran: 3136,
        juz: 19,
        page: 375,
        arab: "\u0623\u064e\u0641\u064e\u0628\u0650\u0639\u064e\u0630\u064e\u0627\u0628\u0650\u0646\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u0639\u0652\u062c\u0650\u0644\u064f\u0648\u0646\u064e",
        transliteration: "Aafabi 'azaabinaa yasta'jiloon",
        translation: "Bukankah mereka yang meminta agar azab Kami dipercepat?",
        shortTafsir: "Bukankah mereka yang meminta agar azab kami dipercepat? Akan tetapi, ketika Kami menimpakan azab itu kepada mereka, mereka meminta agar diberi kesempatan sekali lagi untuk bertobat. Inilah sikap mereka yang saling bertentangan.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3136",
      ),
      Ayah(
        numberInSurah: 205,
        numberInQuran: 3137,
        juz: 19,
        page: 375,
        arab: "\u0623\u064e\u0641\u064e\u0631\u064e\u0623\u064e\u064a\u0652\u062a\u064e \u0625\u0650\u0646 \u0645\u0651\u064e\u062a\u0651\u064e\u0639\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0633\u0650\u0646\u0650\u064a\u0646\u064e",
        transliteration: "Aara'aita im matta'naahum sineen",
        translation: "Maka bagaimana pendapatmu jika kepada mereka Kami berikan kenikmatan hidup beberapa tahun,",
        shortTafsir: "Maka bagaimana pendapatmu, wahai Rasul, jika Kami berikan kepada mereka, orang-orang kafir itu, kenikmatan hidup beberapa tahun.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3137",
      ),
      Ayah(
        numberInSurah: 206,
        numberInQuran: 3138,
        juz: 19,
        page: 375,
        arab: "\u062b\u064f\u0645\u0651\u064e \u062c\u064e\u0627\u0621\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064f\u0648\u0639\u064e\u062f\u064f\u0648\u0646\u064e",
        transliteration: "Summa jaaa'ahum maa kaanoo yoo'adoon",
        translation: "kemudian datang kepada mereka azab yang diancamkan kepada mereka,",
        shortTafsir: "Kemudian datang kepada mereka azab yang telah diancamkan kepada mereka, sebagaimana permintaan mereka agar azab itu dipercepat datangnya.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3138",
      ),
      Ayah(
        numberInSurah: 207,
        numberInQuran: 3139,
        juz: 19,
        page: 376,
        arab: "\u0645\u064e\u0627 \u0623\u064e\u063a\u0652\u0646\u064e\u0649\u0670 \u0639\u064e\u0646\u0652\u0647\u064f\u0645 \u0645\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064f\u0645\u064e\u062a\u0651\u064e\u0639\u064f\u0648\u0646\u064e",
        transliteration: "Maaa aghnaaa 'anhum maa kaanoo yumaatoo'oon",
        translation: "niscaya tidak berguna bagi mereka kenikmatan yang mereka rasakan.",
        shortTafsir: "Niscaya tidak berguna bagi mereka kenikmatan yang mereka rasakan. Kenikmatan di dunia yang pada akhirnya membawa kesengsaraan di akhirat tidaklah berguna.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3139",
      ),
      Ayah(
        numberInSurah: 208,
        numberInQuran: 3140,
        juz: 19,
        page: 376,
        arab: "\u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0647\u0652\u0644\u064e\u0643\u0652\u0646\u064e\u0627 \u0645\u0650\u0646 \u0642\u064e\u0631\u0652\u064a\u064e\u0629\u064d \u0625\u0650\u0644\u0651\u064e\u0627 \u0644\u064e\u0647\u064e\u0627 \u0645\u064f\u0646\u0630\u0650\u0631\u064f\u0648\u0646\u064e",
        transliteration: "Wa maaa ahlaknaa min qaryatin illaa lahaa munziroon",
        translation: "Dan Kami tidak membinasakan sesuatu negeri, kecuali setelah ada orang-orang yang memberi peringatan kepadanya;",
        shortTafsir: "Allah memberikan alasan terhadap siksaan-Nya kepada orang-orang kafir. \"Dan Kami tidak membinasakan sesuatu penduduk negeri mana pun, kecuali setelah ada orang-orang, yaitu para rasul yang memberi peringatan kepadanya, dengan sejelas-jelasnya dan menunjukkan berbagai bukti kebenaran mereka. Aakan tetapi, penduduk negeri tersebut mendustakan mereka. (Lihat: Surah al-Isr\u00e0\u2019/17:15).",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3140",
      ),
      Ayah(
        numberInSurah: 209,
        numberInQuran: 3141,
        juz: 19,
        page: 376,
        arab: "\u0630\u0650\u0643\u0652\u0631\u064e\u0649\u0670 \u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0638\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",
        transliteration: "Zikraa wa maa kunnaa zaalimeen",
        translation: "untuk (menjadi) peringatan. Dan Kami tidak berlaku zalim.",
        shortTafsir: "Hal itu adalah untuk menjadi peringatan bagi yang lain agar tidak melakukan sebagaimana mereka. Dan Kami tidak berlaku zalim, karena Kami telah mengirimkan utusan untuk memperbaiki keadaan. Mestinya mereka bersyukur. Kami berikan peringatan keras kepada mereka, namun mereka mengejek, mendustakan dan menantang (Lihat: Al-Qasas/28: 59).",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3141",
      ),
      Ayah(
        numberInSurah: 210,
        numberInQuran: 3142,
        juz: 19,
        page: 376,
        arab: "\u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u0646\u064e\u0632\u0651\u064e\u0644\u064e\u062a\u0652 \u0628\u0650\u0647\u0650 \u0627\u0644\u0634\u0651\u064e\u064a\u064e\u0627\u0637\u0650\u064a\u0646\u064f",
        transliteration: "Wa maa tanazzalat bihish Shayaateen",
        translation: "Dan (Al-Qur'an) itu tidaklah dibawa turun oleh setan-setan.",
        shortTafsir: "Orang musyrik menuduh bahwa Al-Qur\u2019an itu adalah bisikan setan kepada Nabi Muhammad. Allah membantah dengan tegas tuduhan tersebut. Dan Al-Qur\u2019an itu tidaklah dibawa turun oleh setan-setan. Al-Qur\u2019an berisi hal-hal yang baik dan mulia, mengajak manusia ke jalan yang benar, sementara setan mengajak hal-hal keji dan mungkar dan mengajak kepada jalan yang sesat.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3142",
      ),
      Ayah(
        numberInSurah: 211,
        numberInQuran: 3143,
        juz: 19,
        page: 376,
        arab: "\u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0646\u0628\u064e\u063a\u0650\u064a \u0644\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u0637\u0650\u064a\u0639\u064f\u0648\u0646\u064e",
        transliteration: "Wa maa yambaghee lahum wa maa yastatee'oon",
        translation: "Dan tidaklah pantas bagi mereka (Al-Qur'an itu), dan mereka pun tidak akan sanggup.",
        shortTafsir: "Dan tidaklah pantas bagi mereka Al-Qur\u2019an itu karena hal-hal yang disebutkan di atas dan mereka pun tidak akan sanggup melakukan hal itu, karena Al-Qur\u2019an mempunyai banyak keistimewaan, baik dari segi redaksi maupun isinya, yang tidak akan bisa tertandingi oleh siapa pun (Lihat: Surah al-Isr\u00e0\u2019/17: 88).",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3143",
      ),
      Ayah(
        numberInSurah: 212,
        numberInQuran: 3144,
        juz: 19,
        page: 376,
        arab: "\u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0646\u0650 \u0627\u0644\u0633\u0651\u064e\u0645\u0652\u0639\u0650 \u0644\u064e\u0645\u064e\u0639\u0652\u0632\u064f\u0648\u0644\u064f\u0648\u0646\u064e",
        transliteration: "Innahum 'anis sam'i lama'zooloon",
        translation: "Sesungguhnya untuk mendengarkannya pun mereka dijauhkan.",
        shortTafsir: "Di samping alasan di atas, Allah telah menjaga kesucian Al-Qur\u2019an. Sesungguhnya untuk mendengarkannya pun mereka dijauhkan karena jalan-jalan di langit yang biasa mereka lalui untuk menyadap kabar-kabar langit telah distrilkan dari lalu lalang mereka (Lihat: Surah Jin/72:8-9) sehingga Al-Qur\u2019an bisa sampai kepada nabi secara utuh.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3144",
      ),
      Ayah(
        numberInSurah: 213,
        numberInQuran: 3145,
        juz: 19,
        page: 376,
        arab: "\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u062f\u0652\u0639\u064f \u0645\u064e\u0639\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0644\u064e\u0670\u0647\u064b\u0627 \u0622\u062e\u064e\u0631\u064e \u0641\u064e\u062a\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0639\u064e\u0630\u0651\u064e\u0628\u0650\u064a\u0646\u064e",
        transliteration: "Falaa tad'u ma'al laahi ilaahan aakhara fatakoona minal mu'azzabeen",
        translation: "Maka janganlah kamu menyeru (menyembah) tuhan selain Allah, nanti kamu termasuk orang-orang yang diazab.",
        shortTafsir: "Allah mengingatkan Nabi Muhammad. Maka janganlah sekali-kali kamu menyeru tuhan selain Allah, karena nanti pada hari Kiamat, kamu termasuk orang-orang yang diazab karena dosa syirik itu tidak akan diampuni oleh Allah bagi siapa pun yang tidak bertobat ketika di dunia.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3145",
      ),
      Ayah(
        numberInSurah: 214,
        numberInQuran: 3146,
        juz: 19,
        page: 376,
        arab: "\u0648\u064e\u0623\u064e\u0646\u0630\u0650\u0631\u0652 \u0639\u064e\u0634\u0650\u064a\u0631\u064e\u062a\u064e\u0643\u064e \u0627\u0644\u0652\u0623\u064e\u0642\u0652\u0631\u064e\u0628\u0650\u064a\u0646\u064e",
        transliteration: "Wa anzir 'asheeratakal aqrabeen",
        translation: "Dan berilah peringatan kepada kerabat-kerabatmu (Muhammad) yang terdekat,",
        shortTafsir: "Dan berilah peringatan, wahai Rasul, kepada kerabat-kerabatmu yang terdekat, janganlah mereka menyekutukan Allah, dan ajaklah mereka ke jalan yang benar. Keluarga adalah lingkaran pertama yang harus menjadi prioritas dakwah. Mengandalkan unsur kekerabatan tidak bisa menolong dari siksa Allah jika mereka masih tetap berbuat syirik.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3146",
      ),
      Ayah(
        numberInSurah: 215,
        numberInQuran: 3147,
        juz: 19,
        page: 376,
        arab: "\u0648\u064e\u0627\u062e\u0652\u0641\u0650\u0636\u0652 \u062c\u064e\u0646\u064e\u0627\u062d\u064e\u0643\u064e \u0644\u0650\u0645\u064e\u0646\u0650 \u0627\u062a\u0651\u064e\u0628\u064e\u0639\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",
        transliteration: "Wakhfid janaahaka limanit taba 'aka minal mu'mineen",
        translation: "dan rendahkanlah dirimu terhadap orang-orang yang beriman yang mengikutimu.",
        shortTafsir: "Dan rendahkanlah dirimu terhadap orang-orang yang beriman yang mengikutimu. Jangan kamu bertindak kasar terhadap mereka, karena mereka akan lari darimu, padahal mereka adalah pembantumu yang utama dalam berdakwah. Perjalanan dakwah tidak selamanya mulus. Ada banyak rintangan, antara lain pembelotan dari pengikut.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3147",
      ),
      Ayah(
        numberInSurah: 216,
        numberInQuran: 3148,
        juz: 19,
        page: 376,
        arab: "\u0641\u064e\u0625\u0650\u0646\u0652 \u0639\u064e\u0635\u064e\u0648\u0652\u0643\u064e \u0641\u064e\u0642\u064f\u0644\u0652 \u0625\u0650\u0646\u0651\u0650\u064a \u0628\u064e\u0631\u0650\u064a\u0621\u064c \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",
        transliteration: "Fa in asawka faqul innee bareee'um mimmmaa ta'maloon",
        translation: "Kemudian jika mereka mendurhakaimu maka katakanlah (Muhammad), \u201cSesungguhnya aku tidak bertanggung jawab terhadap apa yang kamu kerjakan.\u201d",
        shortTafsir: "Teruskanlah kamu berdakwah, wahai rasul. Kemudian jika engkau telah berdakwah kepada mereka, tetapi mereka, baik itu keluargamu, orang-orang kafir, atau para pengikutmu, mendurhakaimu dan tidak mengikuti perintahmu, maka katakanlah wahai Rasul, kepada mereka \u201cSesungguhnya aku tidak bertanggung jawab terhadap apa yang kamu kerjakan.\u201d Semua itu menjadi tanggung jawabmu di hadapan Allah.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3148",
      ),
      Ayah(
        numberInSurah: 217,
        numberInQuran: 3149,
        juz: 19,
        page: 376,
        arab: "\u0648\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u0652 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650",
        transliteration: "Wa tawakkal alal 'Azeezir Raheem",
        translation: "Dan bertawakallah kepada (Allah) Yang Mahaperkasa, Maha Penyayang.",
        shortTafsir: "Dan setelah engkau lakukan tugasmu berdakwah kepada mereka, bertawakallah, pasrahkanlah semua urusanmu hanya kepada Allah Yang Mahaperkasa, Mahakuat yang mampu menyiksa siapa pun yang berani menantang-Nya, Maha Penyayang kepada siapa pun yang senantiasa taat kepada-Nya.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3149",
      ),
      Ayah(
        numberInSurah: 218,
        numberInQuran: 3150,
        juz: 19,
        page: 376,
        arab: "\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064e\u0631\u064e\u0627\u0643\u064e \u062d\u0650\u064a\u0646\u064e \u062a\u064e\u0642\u064f\u0648\u0645\u064f",
        transliteration: "Allazee yaraaka heena taqoom",
        translation: "Yang melihat engkau ketika engkau berdiri (untuk salat),",
        shortTafsir: "Dialah Allah yang selalu memerhatikanmu. Dia melihat engkau ketika engkau berdiri dengan penuh ketundukan untuk melakukan salat.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3150",
      ),
      Ayah(
        numberInSurah: 219,
        numberInQuran: 3151,
        juz: 19,
        page: 376,
        arab: "\u0648\u064e\u062a\u064e\u0642\u064e\u0644\u0651\u064f\u0628\u064e\u0643\u064e \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0627\u062c\u0650\u062f\u0650\u064a\u0646\u064e",
        transliteration: "Wa taqallubaka fis saajideen",
        translation: "dan (melihat) perubahan gerakan badanmu di antara orang-orang yang sujud.",
        shortTafsir: "Dan Dia juga melihat perubahan gerakan badanmu di antara orang-orang yang sujud dalam salat, dari berdiri, sampai duduk atau pergerakanmu di antara orang-orang yang beriman, sebagaimana para nabi terdahulu.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3151",
      ),
      Ayah(
        numberInSurah: 220,
        numberInQuran: 3152,
        juz: 19,
        page: 376,
        arab: "\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0647\u064f\u0648\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u0650\u064a\u0639\u064f \u0627\u0644\u0652\u0639\u064e\u0644\u0650\u064a\u0645\u064f",
        transliteration: "Innahoo Huwas Samee'ul 'Aleem",
        translation: "Sungguh, Dia Maha Mendengar, Maha Mengetahui.",
        shortTafsir: "Sungguh, Dia Maha Mendengar semua apa yang kau katakan dan engkau keluhkan, serta Maha Mengetahui apa yang kau kerjakan. Semua yang terjadi tidak berlalu begitu saja, tetapi akan mendapatkan perhitungan dari Allah.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3152",
      ),
      Ayah(
        numberInSurah: 221,
        numberInQuran: 3153,
        juz: 19,
        page: 376,
        arab: "\u0647\u064e\u0644\u0652 \u0623\u064f\u0646\u064e\u0628\u0651\u0650\u0626\u064f\u0643\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0646 \u062a\u064e\u0646\u064e\u0632\u0651\u064e\u0644\u064f \u0627\u0644\u0634\u0651\u064e\u064a\u064e\u0627\u0637\u0650\u064a\u0646\u064f",
        transliteration: "Hal unabbi'ukum 'alaa man tanazzalush Shayaateen",
        translation: "Maukah Aku beritakan kepadamu, kepada siapa setan-setan itu turun?",
        shortTafsir: "Ayat-ayat berikut menjelaskan tentang orang-orang yang mendapat bisikan dari setan dan bekerja sama dengannya untuk menyesatkan manusia. Maukah Aku beritakan kepadamu, wahai orang kafir Mekah, kepada siapa setan-setan itu turun untuk membisikkan kabar bohongnya?",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3153",
      ),
      Ayah(
        numberInSurah: 222,
        numberInQuran: 3154,
        juz: 19,
        page: 376,
        arab: "\u062a\u064e\u0646\u064e\u0632\u0651\u064e\u0644\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0643\u064f\u0644\u0651\u0650 \u0623\u064e\u0641\u0651\u064e\u0627\u0643\u064d \u0623\u064e\u062b\u0650\u064a\u0645\u064d",
        transliteration: "Tanazzalu 'alaa kulli affaakin aseem",
        translation: "Mereka (setan) turun kepada setiap pendusta yang banyak berdosa,",
        shortTafsir: "Mereka, setan-setan itu, tidaklah turun kepada Nabi Muhammad sebagaimana apa yang kamu sangkakan selama ini, tetapi turun kepada setiap pendusta yang membalikkan sesuatu yang buruk menjadi baik dan sebaliknya, yang banyak berdosa dengan melakukan pelanggaran-pelanggaran norma yang tidak dibenarkan oleh agama.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3154",
      ),
      Ayah(
        numberInSurah: 223,
        numberInQuran: 3155,
        juz: 19,
        page: 376,
        arab: "\u064a\u064f\u0644\u0652\u0642\u064f\u0648\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u0652\u0639\u064e \u0648\u064e\u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064f\u0647\u064f\u0645\u0652 \u0643\u064e\u0627\u0630\u0650\u0628\u064f\u0648\u0646\u064e",
        transliteration: "Yulqoonas sam'a wa aksaruhum aaziboon",
        translation: "mereka menyampaikan hasil pendengaran mereka, sedangkan kebanyakan mereka orang-orang pendusta.",
        shortTafsir: "Mereka, para setan itu, menyampaikan hasil pendengaran mereka berupa kabar dari langit yang mereka curi, kemudian mereka mencampurnya dengan sejuta kebohongan, lalu menyampaikannya kepada para dukun, juru ramal dan lainya, sedangkan kebanyakan mereka, para setan atau dukun itu, adalah orang-orang pendusta. Bandingkan hal itu dengan Nabi Muhammad, seorang yang tidak pernah berdusta.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3155",
      ),
      Ayah(
        numberInSurah: 224,
        numberInQuran: 3156,
        juz: 19,
        page: 376,
        arab: "\u0648\u064e\u0627\u0644\u0634\u0651\u064f\u0639\u064e\u0631\u064e\u0627\u0621\u064f \u064a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u063a\u064e\u0627\u0648\u064f\u0648\u0646\u064e",
        transliteration: "Washshu 'araaa'u yattabi 'uhumul ghaawoon",
        translation: "Dan penyair-penyair itu diikuti oleh orang-orang yang sesat.",
        shortTafsir: "Orang kafir Quraisy menuduh Nabi Muhammad sebagai seorang penyair. Allah membantah anggapan itu dengan tegas, \"Dan penyair-penyair itu yang kamu sekalian terpukau dengan syair-syair mereka, diikuti oleh orang-orang yang sesat. Tidak demikian halnya pengikut Nabi Muhammad yang sangat taat kepada aturan-aturan agama.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3156",
      ),
      Ayah(
        numberInSurah: 225,
        numberInQuran: 3157,
        juz: 19,
        page: 376,
        arab: "\u0623\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0631\u064e \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0643\u064f\u0644\u0651\u0650 \u0648\u064e\u0627\u062f\u064d \u064a\u064e\u0647\u0650\u064a\u0645\u064f\u0648\u0646\u064e",
        transliteration: "Alam tara annahum fee kulli waadiny yaheemoon",
        translation: "Tidakkah engkau melihat bahwa mereka mengembara di setiap lembah,",
        shortTafsir: "Tidakkah engkau melihat bahwa mereka mengembara di setiap lembah dengan mengikuti hawa nafsu mereka? Terkadang membenci sesuatu kemudian memujinya dan sebaliknya.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3157",
      ),
      Ayah(
        numberInSurah: 226,
        numberInQuran: 3158,
        juz: 19,
        page: 376,
        arab: "\u0648\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0645\u064e\u0627 \u0644\u064e\u0627 \u064a\u064e\u0641\u0652\u0639\u064e\u0644\u064f\u0648\u0646\u064e",
        transliteration: "Wa annahum yaqooloona ma laa yaf'aloon",
        translation: "dan bahwa mereka mengatakan apa yang mereka sendiri tidak mengerjakan(nya)?",
        shortTafsir: "Dan bahwa mereka mengatakan apa yang mereka sendiri tidak menger-jakan-nya? Inilah bentuk kebohongan mereka. Bandingkan hal ini dengan Nabi Muhammad yang selalu bersikap jujur dalam segala hal.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3158",
      ),
      Ayah(
        numberInSurah: 227,
        numberInQuran: 3159,
        juz: 19,
        page: 376,
        arab: "\u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0648\u064e\u0630\u064e\u0643\u064e\u0631\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627 \u0648\u064e\u0627\u0646\u062a\u064e\u0635\u064e\u0631\u064f\u0648\u0627 \u0645\u0650\u0646 \u0628\u064e\u0639\u0652\u062f\u0650 \u0645\u064e\u0627 \u0638\u064f\u0644\u0650\u0645\u064f\u0648\u0627 \u06d7 \u0648\u064e\u0633\u064e\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0638\u064e\u0644\u064e\u0645\u064f\u0648\u0627 \u0623\u064e\u064a\u0651\u064e \u0645\u064f\u0646\u0642\u064e\u0644\u064e\u0628\u064d \u064a\u064e\u0646\u0642\u064e\u0644\u0650\u0628\u064f\u0648\u0646\u064e",
        transliteration: "Illal lazeena aamanoo w a'amilus saalihaati wa zakarul laaha kaseeranw wantasaroo mim ba'di maa zulimoo; wa saya'lamul lazeena zalamooo aiya munqalbiny yanqaliboon",
        translation: "Kecuali orang-orang (penyair-penyair) yang beriman dan berbuat kebajikan dan banyak mengingat Allah dan mendapat kemenangan setelah terzalimi (karena menjawab puisi-puisi orang-orang kafir). Dan orang-orang yang zalim kelak akan tahu ke tempat mana mereka akan kembali.",
        shortTafsir: "Pada ayat ini diterangkan kriteria penyair yang dikecualikan dari penyair yang disebut di atas. Kecuali orang-orang penyair-penyair yang beriman dengan iman yang benar dan berbuat kebajikan yang sesuai dengan ketentuan syariah dan banyak mengingat Allah, baik siang maupun malam, dan mendapat kemenangan setelah terzalimi karena menjawab puisi-puisi orang-orang kafir. Pada akhir surah ini Allah memberikan peringatan keras terhadap orang-orang kafir. \"Dan orang-orang yang zalim kelak yaitu pada hari kebangkitan, akan tahu ke tempat mana mereka akan kembali. Mereka akan kembali ke neraka.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3159",
      ),
    ],
  );
}
